(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-spec-decode-moe"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-1\">一 · 事故现场：一次 decode 扩容为什么反而更慢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-2\">二 · 机制：γ 个候选、一次并行验证、最长前缀接受</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-3\">三 · 代价：验证批次膨胀与专家容量溢出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-4\">四 · 适用边界：它治什么、不治什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-5\">五 · 标定：γ 由专家容量与带宽上限共同决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-6\">六 · 边界在哪里：一次专家溢出把加速比打成负数的夜班事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-7\">七 · 事故复盘：当“省带宽”的投机解码反而拖垮 TPOT</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-8\">八 · 提议阶段：draft 自回归的输入、输出与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-9\">九 · 验证阶段：一次并行前向如何摊薄权重读取</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-10\">十 · 接受判定：逐位置拒绝采样与最长前缀截断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-11\">十一 · KV 追加：按接受长度批量写回与 page 一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-12\">十二 · 一轮完整流动的代价账与 $\\gamma$ 标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-13\">十三 · 验证批次膨胀与路由偏斜：MoE 投机解码的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-14\">十四 · 接受概率的逐位置推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-15\">十五 · 期望接受长度的闭式解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-16\">十六 · 加速比公式与分母里的隐藏成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-17\">十七 · 伪代码：从公式落到可执行循环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-18\">十八 · 溢出分支与接受率的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-19\">十九 · 加速比公式的适用边界：γ 与专家容量的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-20\">二十 · 请求形态：什么样的流量才喂得饱验证批次</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-21\">二十一 · γ 的标定：加速比公式里的两个隐藏项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-22\">二十二 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-23\">二十三 · 配方表：把请求形态映射到参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-24\">二十四 · 与容量规划的接口：并发上限怎么反推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-25\">二十五 · 负载不对时的工程判断：什么时候该关掉它</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-26\">二十六 · 硬件档位与并行拓扑的确定顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-27\">二十七 · 量化方案的组合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-28\">二十八 · KV 策略：按接受长度批量追加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-29\">二十九 · 调度参数：γ、批大小与容量因子的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-30\">三十 · 可复现的配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-31\">三十一 · 边界标定：γ、专家容量与 KV 追加的一致性约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-32\">三十二 · 验证批膨胀：γ 把 decode 批从“小”推到“大”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-33\">三十三 · 带宽账：摊薄的是权重读取，不是 KV 读取</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-34\">三十四 · 通信账：验证批放大 All-to-All 的消息数与不均衡度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-35\">三十五 · 显存与功耗：draft 模型的固定开销与验证激活值的瞬时峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-36\">三十六 · 接受率与尾延迟：路由不一致如何把算力浪费在拒绝位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-37\">三十七 · 规模上去先崩哪里：三个约束的先后次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-38\">三十八 · 验证批次膨胀与专家容量：MoE 投机解码先崩在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-39\">三十九 · 精度失配：接受率塌陷的三种来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-40\">四十 · OOM：draft 显存与验证批次的乘性占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-41\">四十一 · 批抖动与路由不均：验证批次放大的负载偏斜</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-42\">四十二 · 尾延迟尖刺：KV 截断与 page table 不一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-43\">四十三 · 监控面与回滚阶梯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-44\">四十四 · 当验证批次压垮路由：MoE 投机解码的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-45\">四十五 · 决策维度：把“同族”拆成可比较的四个轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-46\">四十六 · 决策表：五种同族方法的适用条件对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-47\">四十七 · 与量化融合大核的叠加判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-48\">四十八 · 与容量因子路由、专家选择路由的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-49\">四十九 · draft 来源与部署形态的选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-50\">五十 · 选型收口：一张按负载走的判定链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-moe-sec-51\">五十一 · 与相邻算法对照：选型边界与失效条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:527px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 527.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">draft 模型自回归生成 γ 个候选 token 及其概率 q</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">目标 MoE 模型对这 γ 个 token 做一次前向（并行验证），得到概…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">逐位置计算接受概率 min(1, p/q)，采样接受/拒绝，遇到拒绝即截断</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">被接受的 token 追加到 KV cache，被拒绝位置用目标分布重采样…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">若全部接受则额外采一个 bonus token，KV cache 按接受长…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-spec-decode-moe-sec-1\">一 · 事故现场：一次 decode 扩容为什么反而更慢</h3>\n<p>某在线推理服务把 MoE 模型从单卡扩展到多卡，同时把批大小从 8 提到 64，期望吞吐线性上涨。上线后 TPOT 反而恶化：单请求解码时延从可接受区间滑到 SLO 之外，扩容卡越多、单 token 时延越难看。根因不在通信，而在 decode 阶段的算力—带宽结构：MoE 每 token 只激活少量专家，一次前向真正要读的权重只是全部专家参数的一小片，GPU 的 MMA 流水线大量空转，而这一步的时延由权重读取带宽决定。把批加大并不能让单 token 变快——它只是把更多请求的权重读取需求叠在同一时间窗里，带宽仍是瓶颈。扩容买来的是更多闲置算力，不是更低的单 token 时延。</p>\n<p>这就是本算法要解决的推理问题：自回归逐 token 生成无法利用 MoE decode 阶段那批闲置算力。每一次前向只产出 1 个 token，却要完整走一遍路由、专家权重读取、All-to-All 与归约；权重读取次数与 token 数一一对应，带宽被按 token 计费。事故的本质是“用扩容去治带宽受限”，方向错了。正确的方向是让一次权重读取服务多个 token，把带宽成本摊薄——这正是投机解码在 MoE 上的切入点。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-2\">二 · 机制：γ 个候选、一次并行验证、最长前缀接受</h3>\n<p>数据流分四步。第一步，draft 模型自回归生成 γ 个候选 token 及其概率 q；draft 可以是小稠密模型，也可以是 MoE 自身的轻量头，代价是额外显存与计算。第二步，目标 MoE 模型对这 γ 个 token 做一次并行前向，得到每个位置的目标概率 p——注意这里是并行验证，不是逐 token 生成，γ 个 token 共享同一轮专家权重读取。第三步，逐位置按接受概率采样：</p>\n<div class=\"formula\">$$a_i = \\min\\left(1, \\frac{p_i}{q_i}\\right)$$</div>\n<p>从第一个位置起依次判定，遇到拒绝即截断，只保留最长接受前缀；被拒绝的那个位置用目标分布重采样一个 token 补上。第四步，被接受的 token 批量追加进 KV cache；若 γ 个全部接受，再额外采一个 bonus token。整个过程的输出分布与目标 MoE 严格一致——拒绝采样是无偏的，不损失质量，这是它能进生产的前提。</p>\n<p>加速的期望形式可以直接写出来。设单步接受长度为随机变量，γ 为提议长度、α 为单 token 接受率，则每步期望产出 token 数为</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}]=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>分母里的 $c_{\\text{draft}}/c_{\\text{target}}$ 是 draft 前向相对目标前向的单 token 成本比。这个式子说明两件事：γ 增大时分子趋近 $1/(1-\\alpha)$ 饱和，而分母随 γ 线性增长；draft 越便宜、α 越高，加速越明显。在带宽受限的 decode 阶段，材料给出的量级是 2–3 倍加速——但这是有边界的量级，不是无条件承诺。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-3\">三 · 代价：验证批次膨胀与专家容量溢出</h3>\n<p>投机解码在稠密模型上几乎是免费午餐，在 MoE 上不是。验证阶段一次并行处理 γ 个 token，等效批大小被放大 γ 倍；MoE 的路由按 token 独立计算，这 γ 个 draft token 的专家选择分布并不均匀，热点专家被集中命中，容量因子一旦不够就溢出，验证前向被迫拆分或排队。原本想用一次权重读取摊薄 γ 个 token，结果因为溢出变成多次拆分前向，带宽节省被抵消，加速比转负。这是 γ 取值过大的第一类失败模式：验证批次远超 decode 常规批大小，路由分布偏斜，热点专家打满。</p>\n<p>第二类失败模式更隐蔽：draft 模型与目标 MoE 的路由偏好不一致。draft token 是 draft 模型自己“想走”的路径，它在目标 MoE 里命中的专家，与目标模型逐 token 生成时会选的专家并不相同；接受率因此显著低于稠密模型上的预期，验证算力被大量拒绝位置浪费。换句话说，MoE 投机解码的 α 不是稠密模型那个 α，它被路由一致性额外打折。第三类是工程细节：被拒绝位置要用目标分布重采样，KV 追加与截断必须按接受长度批量处理；若 page 归还与批量追加交错，page table 与实际 KV 长度对不上，输出分布出现偏差——这类 bug 不会报错，只会让指标悄悄漂移。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-4\">四 · 适用边界：它治什么、不治什么</h3>\n<p>适用面很窄但很明确：在线低延迟 decode 服务，SLO 以 TPOT 为主，批大小因验证阶段并行处理 γ 个 token 而膨胀，瓶颈确实落在权重读取带宽上。此时投机解码把多次权重读取摊到 γ 个 token 上，是直接对症的。它不解决的问题包括：预填阶段的长序列计算（那是算力受限，不是带宽受限，摊薄权重读取没有意义）；显存容量问题（draft 模型反而多占一份显存，与分页 KV、专家权重共存抢空间）；吞吐导向的离线批处理（那里批已经足够大，带宽已被摊薄，投机解码只增加 draft 开销）；以及路由本身不稳定的场景——专家选择随 draft token 剧烈变化时，接受率撑不起收益。</p>\n<p>与相邻算法的边界也要划清。相比普通自回归 decode，它的差别是把权重读取按 γ 摊薄；相比稠密模型投机解码，MoE 验证阶段路由按 token 独立计算，专家选择随 draft token 变化，接受率与专家负载分布都不同，不能照搬稠密的 γ 标定。容量因子路由与令牌丢弃、专家选择路由这些条目处理的是路由侧的负载均衡，与本条目的验证批次膨胀是互补而非替代关系：前者让路由更均匀，后者让一次前向多产出 token，两者叠加时 γ 的上限由专家容量决定。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-5\">五 · 标定：γ 由专家容量与带宽上限共同决定</h3>\n<p>γ 不是拍脑袋的超参，它是被两个上限夹出来的。上界之一是专家容量：验证批次 = 常规 decode 批 × γ，热点专家的 token 数不能超过容量因子允许的槽位，否则溢出拆分；据此可以反解出给定批大小与路由偏斜下 γ 的最大可行值。上界之二是带宽收益饱和：由上面的期望公式，γ 超过 $1/(1-\\alpha)$ 量级后分子不再增长，分母却继续线性上涨，边际收益转负。两个上界取小，再留出 draft 开销的余量，才是可上线的 γ。</p>\n<p>工程判断上，先测 α 再定 γ：在真实流量分布下用小 γ 探测接受率，若 α 明显低于稠密模型的经验区间，说明 draft 与目标 MoE 的路由偏好不一致，应先换 draft（改用 MoE 自身轻量头往往比外挂小稠密模型更贴合路由），而不是加大 γ。KV 侧按接受长度批量追加、拒绝位置重采样后统一截断，避免 page 归还与追加交错。容量规划时把 draft 模型的显存与算力计入固定开销，把验证批次的峰值显存按 γ 倍预留——这两项不做，2–3 倍的加速会在容量因子上被吃回去。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-6\">六 · 边界在哪里：一次专家溢出把加速比打成负数的夜班事故</h3>\n<p>某在线低延迟 decode 服务在 MoE 模型上启用投机解码，draft 侧用的是同族小稠密模型，γ 按稠密模型的经验值直接照搬。上线后不久，监控上出现一类很难归因的抖动：TPOT 的 P99 在流量并未明显上升的时段突然抬升，而 GPU 利用率反而下降。根因不在 draft 模型，也不在拒绝采样的正确性，而在验证前向本身——γ 个候选 token 被一次性拼进验证批次，批大小从 decode 常规的个位数膨胀到数十，MoE 路由按 token 独立计算，这批 draft token 的专家选择高度偏斜，少数热点专家的容量被打满，验证前向被迫拆分或排队，原本想用并行验证摊薄的权重读取又被拆回多轮。此时加速比公式里的分母被拉长，收益归零甚至为负。这个事故说明：MoE 投机解码解决的是“带宽受限的 decode 阶段算力闲置”这一个具体问题，它不解决专家容量与路由均衡问题，反而会把后者放大。</p>\n<p>把收益写成可核算的形式，边界就清楚了。<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}]=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>其中 α 是逐位置接受概率的期望，$c_{\\text{draft}}$ 与 $c_{\\text{target}}$ 分别是 draft 与目标 MoE 单 token 的代价。分子随 γ 增长但被 α 封顶，分母里的 $\\gamma c_{\\text{draft}}/c_{\\text{target}}$ 是 draft 的显存与计算开销摊薄项。MoE 的特殊性在于 α 不是稠密模型那个值：draft token 命中的专家与逐 token 生成路径不同，路由偏好不一致使 α 显著偏低，分子提前饱和；同时 γ 增大使验证批次膨胀，专家溢出把 $c_{\\text{target}}$ 推高，分母同步恶化。两端夹击之下，γ 存在一个由专家容量与带宽上限共同决定的上界，超过它加速比转负。</p>\n<p>适用边界可以按“解决/不解决”划一条线。它解决的是：每 token 只激活少量专家导致算力闲置、时延受权重读取带宽限制、自回归逐 token 生成无法利用这批闲置算力——把 γ 次权重读取摊到多个 token 上，材料给出的量级是带宽受限 decode 阶段 2–3 倍加速且不损失质量。它不解决：专家并行度与容量规划、路由均衡、draft 与目标模型分布差距过大时的低接受率、KV cache 的 page 管理正确性。最后一项尤其容易出事：被拒绝位置用目标分布重采样、KV 按接受长度批量追加而非逐 token 追加，若 page 归还与批量追加交错处理不当，KV 长度与 page table 会不一致，输出分布出现偏差——这是正确性缺陷，不是性能问题，投机解码的无偏性保证只在 KV 状态严格对应接受前缀时才成立。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>投机解码是否适用</th><th>系统代价落点</th></tr></thead><tbody><tr><td>decode 带宽受限、算力闲置</td><td>适用，摊薄权重读取</td><td>验证批次膨胀带来的显存与路由压力</td></tr><tr><td>专家容量紧张、路由偏斜</td><td>不适用，γ 需按容量标定</td><td>热点专家溢出，验证前向拆分排队</td></tr><tr><td>draft 与目标路由偏好差异大</td><td>收益受限，α 偏低</td><td>验证算力被拒绝位置浪费</td></tr><tr><td>KV page 管理与批量追加未对齐</td><td>不适用，先修正确性</td><td>输出分布偏差，非性能问题</td></tr></tbody></table>\n<p>工程判断落在标定顺序上：先测目标 MoE 在真实批大小下的专家容量上限与路由偏斜度，再据此定 γ 的上界，而不是从稠密模型抄一个 γ；draft 侧优先考虑 MoE 自身的轻量头以缩小路由偏好差距，代价是额外显存与计算；验证阶段的批大小要与 decode 常规批大小合并核算，避免“验证批次远超常规批”这种隐性膨胀。若 α 在实测中明显低于稠密预期、且 γ 放大后 TPOT 不降反升，正确的动作是缩 γ 或退回普通自回归 decode，而不是继续加 γ 赌分子。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-7\">七 · 事故复盘：当“省带宽”的投机解码反而拖垮 TPOT</h3>\n<p>某在线低延迟 decode 服务在 MoE 模型上接入小稠密 draft 模型后，把 γ 从保守值上调，期望把权重读取摊薄到更多 token 上。上线后 TPOT 长尾迅速劣化：验证阶段一次并行处理 γ 个 token，使实际批大小远超常规 decode 批，MoE 路由按 token 独立计算，draft 序列的专家命中分布偏斜，少数热点专家容量溢出，验证前向被迫拆分或排队。此时加速比不再由公式中的期望收益主导：<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}]=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>分母里 draft 的显存与计算开销随 γ 线性增长，而分子因接受率 α 被 MoE 路由不一致压低，收益转负。这正是该算法要解决的具体问题——decode 阶段每 token 只激活少量专家、算力闲置而时延受权重读取带宽限制——但它并不解决专家容量与路由均衡本身。</p>\n<p>边界因此清晰：它把多次权重读取摊到 γ 个 token 上，适用于带宽受限、专家负载尚有余量的 decode 场景，材料给出的量级是 2–3 倍加速且经拒绝采样保证输出无偏；它不适用于专家容量已接近饱和、或 draft 与目标 MoE 路由偏好差异过大的部署。逐位置接受概率为 <span>a_i = min(1, p_i/q_i)</span>，MoE 验证阶段的路由按 token 独立计算，专家选择随 draft token 变化，接受率低于稠密模型预期，被拒绝位置用目标分布重采样时验证算力被大量浪费——这是与稠密投机解码最本质的差别，也是选型时必须先测 α 与专家热点分布的原因。</p>\n<p>系统代价还落在 KV 管理上：被接受 token 需按接受长度批量追加，被拒绝位置重采样一个 token，全部接受则额外采一个 bonus token；若批量追加与 page 归还交错处理不当，KV cache 长度与 page table 不一致，输出分布出现偏差。工程判断是：γ 必须按专家容量与带宽上限标定，而非按稠密模型的接受率经验外推；draft 模型可为小稠密模型或 MoE 自身轻量头，其显存占用要计入容量规划，SLO 以 TPOT 为主时更应保守取 γ。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>收益方向</th><th>失效表现</th></tr></thead><tbody><tr><td>带宽受限、专家有余量</td><td>权重读取摊薄，2–3 倍</td><td>—</td></tr><tr><td>γ 过大、批膨胀</td><td>负收益</td><td>热点专家溢出、验证拆分排队</td></tr><tr><td>路由偏好不一致</td><td>α 偏低</td><td>拒绝位置浪费验证算力</td></tr></tbody></table>\n<h3 id=\"alg-spec-decode-moe-sec-8\">八 · 提议阶段：draft 自回归的输入、输出与代价</h3>\n<p>数据流的第一段发生在 draft 侧。输入是当前请求已确认的上下文 KV（长度记为 $L$）与最后一个被接受的 token，输出是 $\\gamma$ 个候选 token 及其对应的 draft 概率 $q_1,\\dots,q_\\gamma$。draft 模型逐位置自回归：第 $i$ 步以 $L+i-1$ 长度的上下文前向一次，采样出 $t_i$，把 $t_i$ 追加进 draft 自己的 KV 后再算第 $i+1$ 步。注意这一步是串行的，$\\gamma$ 次前向无法合并，因为每个候选都依赖前一个候选。</p>\n<p>代价结构因此很清晰：draft 侧的时延近似 $\\gamma \\cdot c_{\\text{draft}}$，其中 $c_{\\text{draft}}$ 是单次 draft 前向的墙钟时间。若 draft 是小稠密模型，$c_{\\text{draft}}$ 由它的权重读取带宽决定，与目标 MoE 的单 token 时延同量级但绝对值小得多；若 draft 是 MoE 自身的轻量头（例如复用目标模型的部分层或一个极窄的预测头），则 $c_{\\text{draft}}$ 里还混入了目标模型的部分权重读取，摊销效果变差。显存上，draft 权重是常驻开销，与目标 MoE 的分页 KV 和专家权重争抢同一块 HBM，这是部署配方里必须预留的固定成本。</p>\n<p>工程上还有一个容易被忽略的输入约束：draft 采样必须记录 $q_i$ 的完整分布（至少是被采样 token 处的概率），否则验证阶段无法算比值。若 draft 侧为了省显存只保留 top-k 概率，接受概率的计算就要退化为近似式，破坏无偏性。因此提议阶段的输出不是\"γ 个 token\"，而是\"γ 个 (token, q) 对\"，这是后续所有步骤的契约。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-9\">九 · 验证阶段：一次并行前向如何摊薄权重读取</h3>\n<p>第二段是整条流水线收益的来源。输入是 $\\gamma$ 个候选 token 拼成的验证批次，加上原上下文 KV；输出是目标 MoE 对这 $\\gamma$ 个位置的概率 $p_1,\\dots,p_\\gamma$。关键机制是因果掩码下的并行前向：$\\gamma$ 个 token 作为一条长度为 $\\gamma$ 的序列一次喂入，注意力在序列内部因果可见，因此第 $i$ 个位置的输出只依赖前 $i$ 个候选，与逐 token 生成完全等价。目标 MoE 的专家权重在这一步只被读取一遍，却服务了 $\\gamma$ 个位置——这正是把带宽受限的 decode 从\"每 token 读一次权重\"变成\"每 $\\gamma$ 个 token 读一次权重\"的杠杆。</p>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}},\\quad \\mathbb{E}[\\text{tokens/step}]=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha}$$</div>\n<p>分母里的 $\\gamma c_{\\text{draft}}/c_{\\text{target}}$ 是 draft 串行开销相对目标单次前向的折算，分子是每轮验证平均产出的 token 数，$\\alpha$ 为单位置接受率。这条式子说明两件事：$\\gamma$ 增大时分子趋于饱和（几何级数上限 $1/(1-\\alpha)$），分母却线性增长，所以 $\\gamma$ 存在最优点；而 $\\alpha$ 一旦因 MoE 路由偏移而下降，分子立刻缩水，加速比随之塌陷。</p>\n<p>验证阶段的代价不在算力而在批形。$\\gamma$ 个 token 让验证批大小相对常规 decode 膨胀了 $\\gamma$ 倍，MoE 路由按 token 独立计算，$\\gamma$ 个位置的专家选择叠加后，热点专家的 token 数可能远超单 token 时的分布。容量因子一旦被击穿，验证前向被迫拆分或排队，原本一次权重读取被拆成多次，摊销收益归零。因此验证阶段的真实输入不只是 token，还包括\"这批 token 的路由分布是否落在专家容量内\"这一约束。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-10\">十 · 接受判定：逐位置拒绝采样与最长前缀截断</h3>\n<p>第三段是纯逻辑步骤，几乎不耗算力但决定正确性。输入是成对的 $(p_i,q_i)$，输出是接受长度 $n$（$0\\le n\\le\\gamma$）。逐位置计算接受概率并采样：</p>\n<div class=\"formula\">$$a_i=\\min\\left(1,\\frac{p_i}{q_i}\\right)$$</div>\n<p>从 $i=1$ 起依次以 $a_i$ 的概率接受，遇到第一个拒绝即截断，后续位置即使采样通过也一律丢弃——这是\"最长前缀\"语义，因为第 $i+1$ 个候选的上下文依赖第 $i$ 个候选被接受。截断后在被拒绝的那个位置上，用目标分布的重采样补一个 token：把目标分布减去 draft 分布的残余质量归一化后采样，保证最终输出分布严格等于目标 MoE 的分布。若 $\\gamma$ 个位置全部接受，则额外从目标模型采一个 bonus token，这一位不经过拒绝采样，直接取自 $p$ 的下一位置。</p>\n<p>这一步的代价是数值精度与分支控制。$p_i/q_i$ 在 NVFP4/FP8 量化的目标模型上不是精确比值：$p_i$ 来自量化后的 logits，$q_i$ 来自 draft 的概率输出，两者精度档位不同，比值在 $q_i$ 很小时会被放大。工程上通常在对数域做减法再取指数，并对 $q_i$ 设下限，避免除零与溢出。另一个代价是控制流的串行性：接受判定必须逐位置进行，无法向量化成一次并行比较，但它是纯标量运算，相对验证前向的时延可忽略。真正昂贵的是拒绝带来的浪费——被拒绝位置之后的候选全部作废，验证阶段为它们付出的专家权重读取与路由计算白费，这正是 $\\alpha$ 偏低时加速比转负的微观来源。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-11\">十一 · KV 追加：按接受长度批量写回与 page 一致性</h3>\n<p>第四段把逻辑结果落回显存。输入是接受长度 $n$、被接受的 $n$ 个 token（若发生拒绝还包括重采样出的那一个），输出是更新后的 KV cache 与 page table。机制要点是批量追加而非逐 token 追加：一次性为 $n+1$ 个位置分配 page、写入这 $n+1$ 个位置的 K/V、更新序列长度。分页 KV 下，批量追加把 $n+1$ 次小的分配与元数据更新合并成一次，减少 page 归还与再分配的交错。</p>\n<p>代价体现在碎片与一致性两处。若按逐 token 追加，每个 token 都要走一次 page 分配路径，$\\gamma$ 个候选在被拒绝时还要把已写入的 page 归还，归还与追加交错会让 page table 与逻辑长度短暂不一致。批量追加的写法是：先按 $n+1$ 预算 page，写入被接受前缀与重采样 token，再统一提交长度；被拒绝位置的候选 KV 从未写入，也就不需要归还。这条路径的显存代价是瞬时多占 $n+1$ 个位置的 KV，对长上下文请求而言这部分容量必须提前计入容量规划，否则批量追加会在高水位时触发抢占。</p>\n<p>还有一个与 draft 侧耦合的细节：draft 模型自己的 KV 在提议阶段已经写入了 $\\gamma$ 个候选，验证后被拒绝的那些位置必须回滚到接受长度，否则下一轮提议会以错误的上下文起步。draft KV 的回滚与目标 KV 的追加必须用同一个 $n$ 对齐，这是两条 KV 流之间唯一的同步点，也是实现中最容易出错的接缝。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-12\">十二 · 一轮完整流动的代价账与 $\\gamma$ 标定</h3>\n<p>把五段串起来看一轮的代价：提议 $\\gamma c_{\\text{draft}}$，验证一次目标前向（权重读取摊到 $\\gamma$ 个位置），接受判定可忽略，KV 批量追加一次元数据操作，回滚 draft KV 一次。整轮产出 $\\mathbb{E}[\\text{tokens/step}]$ 个 token，于是每 token 摊销的权重读取约为单次目标前向的 $1/\\mathbb{E}[\\text{tokens/step}]$。当 $\\alpha$ 接近 1 时这个摊销很可观，材料给出的量级是带宽受限 decode 阶段 2–3 倍加速；当 $\\alpha$ 掉到 0.5 以下，$\\gamma$ 再大也只能把摊销压到 2 倍以内，而分母的 draft 串行开销开始占主导。</p>\n<p>MoE 让 $\\alpha$ 的估计比稠密模型复杂。draft token 的专家选择与逐 token 生成路径不同：逐 token 时每个位置的路由只看到真实前缀，而 draft 候选是由 draft 模型\"想象\"出来的，目标 MoE 对它们的路由可能落在与真实分布不同的专家上，导致 $p_i$ 与 $q_i$ 的失配比稠密情形更大。因此 $\\gamma$ 的标定不能只看 draft 模型的离线接受率，必须在目标 MoE 的真实路由分布下测：以专家容量为上限反推单轮可容纳的验证 token 数，再以带宽上限反推摊销收益的拐点，两者取小。工程判断是：$\\gamma$ 应按\"验证批次不击穿容量因子\"与\"$\\gamma c_{\\text{draft}}/c_{\\text{target}}$ 不超过摊销收益\"两条约束同时定，任一约束被违反，加速比就转负。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>提议</td><td>已确认 KV、末 token</td><td>$\\gamma$ 个 (token, $q$)</td><td>$\\gamma c_{\\text{draft}}$ 串行时延、draft 权重常驻显存</td></tr><tr><td>验证</td><td>$\\gamma$ 候选、上下文 KV</td><td>$p_1,\\dots,p_\\gamma$</td><td>批形膨胀 $\\gamma$ 倍、专家容量与路由偏斜</td></tr><tr><td>接受判定</td><td>$(p_i,q_i)$ 对</td><td>接受长度 $n$、重采样 token</td><td>标量串行、量化比值精度、拒绝位置算力浪费</td></tr><tr><td>KV 追加</td><td>$n$、重采样 token</td><td>更新后的 KV 与 page table</td><td>瞬时多占 $n+1$ 位置、page 一致性</td></tr><tr><td>draft 回滚</td><td>$n$</td><td>对齐后的 draft KV</td><td>两条 KV 流的同步接缝</td></tr></tbody></table>\n<p>失败模式在这一步最集中：$\\gamma$ 过大使验证批次远超 decode 常规批大小，路由分布偏斜让热点专家溢出，验证前向被迫拆分，摊销收益被拆没；draft 与目标 MoE 的路由偏好不一致让接受率显著低于稠密预期，验证算力被大量拒绝位置浪费；KV 追加与截断处理不当则让 page table 与逻辑长度错位，输出分布出现偏差。这三条都不是调参能绕过的，必须在步骤设计里就把 $\\gamma$ 的上界、路由容量的检查、以及批量追加的原子性写进数据流。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-13\">十三 · 验证批次膨胀与路由偏斜：MoE 投机解码的失效边界</h3>\n<p>按数据流把一次投机步拆开看，代价集中在第三步。第一步 draft 自回归生成 γ 个候选，输入是当前 KV 前缀，输出 γ 组 (token, q)，代价是 γ 次串行小模型前向，显存上多驻留一份 draft 权重，计算上占用本可用于验证的 SM。第二步目标 MoE 并行验证，输入是 γ 个候选拼成的验证批次，输出逐位置 p，代价是一次权重读取摊到 γ 个 token 上——这正是收益来源。第三步逐位置按 <span class=\"formula\">$$a_i = \\min\\left(1, \\frac{p_i}{q_i}\\right)$$</span> 采样接受或拒绝，遇拒绝即截断；第四步按接受长度批量追加 KV，被拒绝位置用目标分布重采样一个 token，全接受则补一个 bonus token。真正决定这套方案成败的不是接受率本身，而是第二步的批次形态与专家负载。</p>\n<p>边界条件可以写成一条判据：验证批次的专家负载必须落在单卡专家容量之内。γ 个 draft token 的路由是逐 token 独立计算的，专家选择随 draft token 变化，与逐 token 生成路径的专家命中并不一致。当 γ 拉大，验证批次远超 decode 常规批大小，路由分布偏斜，热点专家容量溢出，验证前向被迫拆分或排队，摊薄权重读取的收益被拆分开销吃掉，加速比转为负收益。用公式表达，实际加速比要乘上一个验证效率折损项：</p>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}\\cdot\\eta_{\\text{route}},\\quad \\eta_{\\text{route}}=\\frac{\\text{有效专家并行度}}{\\text{峰值专家并行度}}$$</div>\n<p>η_route 在稠密模型上接近 1，在 MoE 上随 γ 与路由偏斜单调下降，材料给出的 2–3 倍加速只在 η_route 未塌缩的区间成立。工程判断是：γ 不能按稠密模型的接受率曲线标定，而要按专家容量与权重读取带宽上限联合标定，取“验证批次刚好填满专家容量、又不触发拆分”的拐点。</p>\n<p>第二类失效来自接受率的结构性折损。draft 模型与目标 MoE 的路由偏好不一致，draft token 命中的专家与逐 token 生成路径不同，接受率显著低于稠密模型预期，验证算力被大量拒绝位置浪费——这些位置仍走完了完整前向，却只换回一个重采样 token。第三类失效在 KV 侧：被拒绝位置重采样时若 KV 追加与截断处理不当，page 归还与批量追加交错，会造成 KV cache 长度与 page table 不一致，输出分布出现偏差；批量追加虽减少碎片，但要求截断与归还严格按接受长度原子完成。三类失效的共同点是：draft 的显存与计算开销是固定支出，而验证阶段的收益随 γ、路由偏斜、接受率三者联动衰减，因此调度器应把 γ 作为随批内请求形态动态收缩的变量，而非全局常量。</p>\n<h3 id=\"alg-spec-decode-moe-sec-14\">十四 · 接受概率的逐位置推导</h3>\n<p>投机解码的无偏性不是工程近似，而是一条可以逐项写出的概率恒等式。设 draft 模型对第 i 个候选位置给出分布 q_i，目标 MoE 模型给出 p_i。验证阶段对候选 token x 以概率 a_i = min(1, p_i(x)/q_i(x)) 接受；若拒绝，则从残差分布 r_i(x) ∝ max(0, p_i(x) − q_i(x)) 重采样一个 token。要证明最终输出服从 p_i，只需验证对任意 token y，其被输出的总概率等于 p_i(y)：</p>\n<div class=\"formula\">$$P(\\text{输出 } y) = q_i(y)\\,a_i(y) + \\Big(1 - \\textstyle\\sum_{x} q_i(x)a_i(x)\\Big)\\, r_i(y)$$</div>\n<p>关键一步在于把接受质量与残差质量配平。当 p_i(y) ≤ q_i(y) 时，a_i(y) = p_i(y)/q_i(y)，第一项恰为 p_i(y)，而 r_i(y) = 0，无需第二项补偿；当 p_i(y) > q_i(y) 时，a_i(y) = 1，第一项为 q_i(y)，差额 p_i(y) − q_i(y) 正好由残差分布按总拒绝质量归一化后补齐。总拒绝质量等于 1 − Σ_x min(q_i(x), p_i(x))，而残差未归一化质量之和恰为 Σ_x max(0, p_i(x) − q_i(x))，两者相等，于是第二项系数与 r_i 的归一化因子相消。这一步是整个算法成立的地基：它说明拒绝采样不是“近似地”恢复目标分布，而是精确恢复，因此 MoE 目标模型的输出质量不因引入 draft 而下降。</p>\n<p>工程含义在于，接受概率的分母 q_i 必须是 draft 模型实际采样时用的分布，而不是任何近似或截断后的分布。若 draft 侧为了省显存对 logits 做了量化或 top-k 截断，却仍用原始 q_i 计算 a_i，恒等式即被破坏，输出会出现系统性偏差。系统代价体现在验证前向必须保留每个候选位置的完整目标 logits（至少是被采样位置的 p_i 值），这要求验证 kernel 在并行处理 γ 个 token 时把每行 logits 的对应分量取出并跨步写回，增加了验证阶段的寄存器与共享内存压力，但相比权重读取带宽，这部分开销可以忽略。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-15\">十五 · 期望接受长度的闭式解</h3>\n<p>设每个位置的接受概率独立同分布，记单位置接受率为 α（即 a_i 的期望），则一次投机轮次中被接受的前缀长度服从截断几何分布。令 K 为接受长度，K ∈ {0,1,…,γ}，其中 K = γ 表示全部接受并额外获得一个 bonus token。于是每步产出 token 数的期望为：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}]=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha}$$</div>\n<p>推导的关键一步是把“全部接受”这一分支单独计入：前 γ 个位置全部接受的概率为 α^γ，此时产出 γ + 1 个 token（含 bonus），其余分支在第 k 个位置首次拒绝时产出 k 个 token，概率为 α^k(1−α)。对 k 从 0 到 γ−1 求和并加上 α^γ(γ+1)，化简即得上式。注意 α = 1 时该式退化为 γ + 1，符合直觉；α = 0 时退化为 1，即完全退化为普通自回归 decode，此时投机轮次没有收益。</p>\n<p>这个式子给出两条工程判断。第一，γ 的边际收益递减极快：当 α 中等（例如 0.6 量级），γ 从 2 增到 4 带来的期望 token 数增长有限，而验证批次规模翻倍，MoE 路由的负载偏斜风险随之上升。第二，α 是 MoE 投机解码中最不可控的变量——它不由 γ 决定，而由 draft 与目标 MoE 的路由一致性决定。稠密模型上 draft 与目标共享同一套参数路径，α 较高；MoE 上每个 token 的专家选择独立计算，draft token 命中的专家子集与逐 token 生成路径不同，α 系统性偏低。因此同一套 γ 标定在稠密模型上有效，搬到 MoE 上会高估收益。吞吐代价上，验证阶段一次前向处理 γ 个 token，激活专家数随 token 数线性增长，若 γ 超过专家容量因子允许的范围，热点专家溢出会把验证前向拆成多次，反而拉长 TPOT。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-16\">十六 · 加速比公式与分母里的隐藏成本</h3>\n<p>加速比不能只看期望 token 数，必须把 draft 的串行成本放进分母：</p>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>这里 c_draft 是 draft 模型生成单个 token 的成本，c_target 是目标 MoE 验证一次前向的成本，γ·c_draft/c_target 表示 draft 自回归 γ 步相对于一次目标验证的相对开销。关键一步是把 draft 的 γ 步视为串行累加：draft 是自回归的，γ 个 token 必须逐个生成，无法并行；而目标验证是一次并行前向，γ 个 token 共享一次权重读取。这正是收益的来源——分母中的 1 代表这次共享读取，分子中的期望 token 数代表它摊薄到的产出。</p>\n<p>把 MoE 的特性代入分母会发现一个容易被忽略的项：c_target 在 MoE 上并非与 γ 无关。验证批次从常规 decode 批大小膨胀到 γ 倍后，路由分布偏斜使部分专家被反复命中，专家权重的读取次数不再是一次，而是按热点专家的溢出次数增加。也就是说 c_target 随 γ 上升而上升，分母的增长比稠密模型更快，加速比曲线更早出现拐点。材料给出的 2–3 倍加速对应的是带宽受限、γ 经标定、专家容量未溢出的区间；一旦 γ 越过专家容量上限，c_target 的膨胀会吞掉分子收益，加速比转为负。工程上应把 γ 的上界直接绑定到专家容量因子与单卡专家权重带宽，而不是绑定到“期望 token 数最大化”。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-17\">十七 · 伪代码：从公式落到可执行循环</h3>\n<p>下面的伪代码把上述公式落成一次投机轮次的完整控制流，重点在 KV 追加与截断的原子性：</p>\n<ul>\n<li>输入：当前 KV 长度 L、draft 模型 D、目标 MoE 模型 T、候选长度 γ、专家容量上限 C。</li>\n<li>步骤 1：D 自回归生成 γ 个 token 及对应 q_i，同时把 draft 侧的 KV 写入临时页，不进入主 page table。</li>\n<li>步骤 2：构造验证批次，把这 γ 个 token 与当前上下文拼成一次前向输入，T 并行前向得到每个位置的 p_i；路由按 token 独立计算，逐 token 统计各专家命中数，若任一专家命中数超过 C 则触发溢出分支。</li>\n<li>步骤 3：对 i 从 1 到 γ 依次采样 u_i ~ Uniform(0,1)，若 u_i ≤ min(1, p_i/q_i) 则接受并继续，否则在该位置停止，记接受长度 k = i − 1。</li>\n<li>步骤 4：若 k &lt; γ，用残差分布 r_k 在拒绝位置重采样一个 token，作为第 k+1 个输出；若 k = γ，额外从 p 采一个 bonus token。</li>\n<li>步骤 5：把 k 个已接受 token 与重采样/bonus token 批量追加到主 KV cache，一次性推进 page table 的 L 到 L + k + 1；draft 临时页按接受长度归还或丢弃。</li>\n</ul>\n<p>伪代码里有两处必须写成原子操作。其一是步骤 3 的逐位置采样必须严格按顺序进行，不能并行采样后再取最长前缀——因为拒绝位置之后的候选 token 在概率上依赖于前面被接受的事实，乱序采样会破坏无偏性。其二是步骤 5 的批量追加：若把追加与截断交错执行，page 归还与批量写入可能造成 page table 长度与实际 KV 内容不一致，输出分布出现偏差。系统代价上，步骤 2 的验证前向是整轮唯一的大 kernel，其耗时由专家权重读取带宽决定；步骤 1 的 γ 次 draft 前向是串行小 kernel，其耗时由 draft 模型的显存带宽与 kernel 启动开销决定，γ 越大这部分越不可忽略，这正是加速比公式分母中 γ·c_draft 项的来源。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-18\">十八 · 溢出分支与接受率的耦合</h3>\n<p>验证批次的专家命中统计不是事后诊断，而应作为 γ 的在线反馈信号。设验证批次中第 e 个专家的命中数为 n_e，容量为 C_e，则溢出判据为 max_e n_e &gt; C_e。关键一步是把 γ 的选择写成受容量约束的优化：在给定当前批大小 B 与专家容量 C 下，验证批次规模为 B·γ，路由偏斜使热点专家的期望命中数约为 B·γ·π_e（π_e 为该专家在 draft token 分布下的命中比例），因此 γ 的上界近似为 C/(B·π_max)。这个式子说明 γ 不是常数，而应随批大小与路由偏斜动态收缩：在线低延迟服务中批大小本身随负载波动，固定 γ 在低负载时浪费算力、在高负载时触发溢出。</p>\n<p>接受率与溢出之间存在负反馈。γ 增大使验证批次膨胀，路由偏斜加剧，热点专家溢出导致验证前向被拆分，拆分后的多次前向使 c_target 上升；同时 draft 模型在更长候选上自回归，其分布与目标 MoE 的路由偏好偏离更远，α 下降。两者叠加使实际加速比远低于用固定 α 代入公式的估计。工程判断是：把 α 的在线估计（每轮接受长度 k 的滑动平均）与专家命中统计一起作为 γ 控制器的输入，当 α 下降或 max_e n_e 逼近 C_e 时收缩 γ，而不是等溢出发生后再回退。代价是控制器本身引入少量调度开销，但相比一次溢出导致的验证前向拆分与 TPOT 抖动，这笔开销是值得的。</p>\n<p>最后落到一个具体机制上：验证前向的路由结果应在 kernel 内直接产出每专家命中计数并写入全局计数器，供下一轮的 γ 决策读取，避免额外的 host 同步；KV 追加则以接受长度为单位批量提交，page table 更新与计数器读取在同一调度步内完成。这样公式里的 α、γ、C 三个量在运行时形成闭环，投机解码在 MoE 上才不会退化为“公式好看、实测负收益”的形态。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-19\">十九 · 加速比公式的适用边界：γ 与专家容量的耦合</h3>\n<p>把接受率写成逐位置形式 $a_i=\\min(1,p_i/q_i)$，整段前缀全接受的概率就是 $\\prod_{i\\le k}a_i$；若近似为每位置独立同分布、平均接受率 $\\alpha$，则一步产出的期望 token 数正是 $\\mathbb{E}[\\text{tokens/step}]=(1-\\alpha^{\\gamma+1})/(1-\\alpha)$，其中 $\\gamma+1$ 的额外一项来自全接受后补采的 bonus token。分母 $1+\\gamma c_{\\text{draft}}/c_{\\text{target}}$ 是代价项：draft 自回归 $\\gamma$ 步的耗时与目标 MoE 一次并行验证前向的耗时之比，乘以 $\\gamma$ 后与收益项相除。这个式子隐含一个前提——验证前向的耗时与 $\\gamma$ 近似无关，也就是专家权重只读一次、算力仍有余量。一旦 $\\gamma$ 把验证批次推过专家容量阈值，$c_{\\text{target}}$ 随 $\\gamma$ 上升，分母不再是常数，公式失效，加速比可能跌破 1。</p>\n<p>MoE 特有的偏差在于 $\\alpha$ 不是稠密模型那个 $\\alpha$。验证阶段每个 draft token 独立走路由，专家选择随 token 内容变化；而逐 token 生成时，同一请求的路由在时间上是连续的，热点专家被反复命中。draft 模型（无论小稠密模型还是 MoE 轻量头）的路由偏好与目标 MoE 不一致，导致 $p_i/q_i$ 在路由分歧位置显著偏小，$\\alpha$ 被拉低。工程上的判断是：$\\gamma$ 应按“最热专家的容量上限”而非按带宽上限单独标定，取两者中更紧的那个。可用一张小表把边界条件摆清楚：</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>γ 过大，验证批次超专家容量</td><td>热点专家溢出、验证前向被拆分或排队</td><td>TPOT 抖动，加速比转负</td></tr><tr><td>draft 与目标路由偏好分歧</td><td>逐位置接受率在特定专家上塌陷</td><td>验证算力被拒绝位置浪费</td></tr><tr><td>KV 批量追加与截断交错</td><td>page table 长度与逻辑长度不一致</td><td>输出分布出现偏差，需回滚</td></tr></tbody></table>\n<p>伪代码落到可实现层面，关键是把“接受最长前缀”与“KV 批量追加”做成一个原子步骤，避免逐位置追加带来的 page 碎片：先生成 $\\gamma$ 个 draft token 及其 $q_i$，目标模型一次前向得到 $p_i$；从 $i=1$ 起采样 $u_i\\sim U(0,1)$，若 $u_i\\le\\min(1,p_i/q_i)$ 则接受并继续，否则在该位置用残差分布 $\\max(0,p_i-q_i)$ 归一化后重采样一个 token 并截断；记接受长度为 $L$，一次性把 $L$ 个 token（含重采样位或 bonus token）写入 KV，按 $L$ 而非按 1 推进 page 分配。被拒绝位置的残差重采样是保证无偏的那一步，漏掉它分布就会偏向 draft。</p>\n<p>系统代价要按 SLO 口径核算：验证批次膨胀使单次前向的显存占用与路由开销上升，draft 模型常驻显存挤占 KV 预算，两者共同压缩可承载的并发请求数；在 TPOT 为主的在线低延迟服务里，γ 的收益必须用“每步摊薄后的权重读取次数”衡量，而不是单看接受率。材料给出的 2–3 倍加速对应带宽受限、专家容量尚有余量的区间；越过该区间，收益被专家溢出与路由分歧吃掉，此时正确动作是下调 γ 或改用按专家容量分档的自适应 γ，而不是继续加大 draft 长度。</p>\n<h3 id=\"alg-spec-decode-moe-sec-20\">二十 · 请求形态：什么样的流量才喂得饱验证批次</h3>\n<p>投机解码在 MoE 上的收益来源只有一个：把 γ 个候选 token 塞进同一次目标前向，让专家权重只被读一遍。这决定了它对请求形态的偏好极其挑剔——必须是<strong>在线低延迟 decode 服务</strong>，且请求本身已经进入稳定解码期。预填阶段（prefill）的长序列对投机解码没有意义：预填本来就是计算密集、权重读取被充分摊薄，验证批次再膨胀也只是徒增激活显存。真正吃到红利的是那些 prompt 短、输出长、且并发稳定的对话式或代码补全式流量。</p>\n<p>长度分布是第二个筛子。若输出长度分布重尾（少数请求生成上千 token，多数几十 token 就结束），则短请求在 γ 个候选还没攒满时就已终止，验证批次的有效利用率被拉低；长请求则持续处于带宽受限区间，是投机解码的理想载体。工程上判断一个负载是否适配，看的是<strong>输出长度中位数与 P99 的比值</strong>，以及解码步数占总步数的比例——这个比例越高，摊薄权重读取的机会越多。</p>\n<p>并发与批大小在这里发生了一次结构性错位。常规 decode 的批大小按“每步 token 数”计，而验证阶段一次并行处理 γ 个 token，等效批大小变为 $B \\times \\gamma$（B 为并发请求数）。这意味着原本精心标定的批大小在开启投机后瞬间越界：显存中的激活缓冲、路由中间结果、专家分组的临时空间全部按 γ 倍膨胀。负载配方要做的第一件事，是把并发上限按 γ 反推重算，而不是沿用关闭投机时的批大小配置。</p>\n<p>具体例子：一个在线客服模型，并发 64、每请求平均输出 300 token、TPOT SLO 压在数十毫秒量级。关闭投机时批大小 64 已接近显存与带宽的平衡点；开启 γ=4 的投机后，验证批次等效 256 token，若仍按 64 并发调度，单步激活显存与路由临时缓冲直接翻四倍，最先崩的是专家分组的临时空间而非 KV cache。正确做法是把并发降到 16 左右，让 $B\\times\\gamma$ 回到原批大小附近，用更少的并发换更长的单步——这正是负载配方与容量规划的耦合点。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-21\">二十一 · γ 的标定：加速比公式里的两个隐藏项</h3>\n<p>前文给出的加速比近似式 $\\text{speedup}\\approx \\mathbb{E}[\\text{tokens/step}]/(1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}})$ 在负载配方里要拆开看。分子 $\\mathbb{E}[\\text{tokens/step}]=(1-\\alpha^{\\gamma+1})/(1-\\alpha)$ 由接受率 α 与 γ 共同决定，分母里的 $c_{\\text{draft}}/c_{\\text{target}}$ 是 draft 前向与目标前向的单步代价比。稠密模型上 α 随 γ 缓慢衰减，分子近似线性增长；MoE 上 α 的衰减更陡，因为路由对 draft token 的专家选择与逐 token 生成路径不一致——draft 模型提议的 token 落在哪些专家上，与目标 MoE 逐 token 解码时会激活的专家集合存在系统性偏差。</p>\n<p>于是 γ 的标定不是“越大越好”的单调问题，而是两个相反力量的平衡：γ 增大使分子趋近 $1/(1-\\alpha)$ 的上限，但同时让验证批次膨胀、路由分布偏斜、热点专家容量溢出，分母的实际代价（含验证前向被迫拆分或排队）非线性上升。工程判断是：<strong>γ 应按专家容量与带宽上限标定，而不是按接受率上限标定</strong>。先测出在给定并发下、验证批次不触发专家溢出的最大 γ，再在这个上限内看 α 是否还值得继续加长。</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}]=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>代价侧的量化：draft 模型无论多小都占一份显存与一份计算。若 draft 是独立小稠密模型，它要在每个验证步前自回归跑 γ 次，这 γ 次前向的时延直接叠加在 TPOT 上；若 draft 是 MoE 自身的轻量头，则省了独立权重但多了一次头前向的路由开销。两种方案在负载配方上的差别是：前者适合并发不高、TPOT 有余量的场景，后者适合显存吃紧、但能容忍 draft 与目标共享路由结构的场景。材料未给出具体 γ 与 SLO 数值，因此标定必须落在实测曲线上，而非套用稠密模型的推荐值。</p>\n<p>具体例子：同一客服负载，γ 从 2 加到 4 时 $\\mathbb{E}[\\text{tokens/step}]$ 从约 1.8 升到约 2.6，但验证批次从 128 涨到 256，触发两个热点专家的容量溢出，验证前向被拆成两次，等效 $c_{\\text{target}}$ 翻倍，加速比反而从 1.9 掉到 1.2。这就是“γ 过大抵消收益”的典型形态——分子还在涨，分母涨得更快。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-22\">二十二 · 负载不对时的三种崩法</h3>\n<p><strong>崩法一：验证批次远超 decode 常规批大小，路由偏斜引爆热点专家。</strong>MoE 路由按 token 独立计算，γ 个 draft token 的专家分布不会均匀铺开，而是集中在少数被 draft 模型偏好的专家上。批大小膨胀 γ 倍后，这些热点专家的容量因子被瞬间击穿，验证前向被迫拆分或排队，单步时延跳变。这不是显存不够，而是<strong>专家容量与批大小的匹配被 γ 打破</strong>。表现是 TPOT 的 P99 出现规律性尖峰，且尖峰周期与 γ 同步。</p>\n<p><strong>崩法二：接受率低于稠密预期，验证算力被拒绝位置浪费。</strong>MoE 的路由偏好与 draft 模型不一致，导致 draft token 命中的专家与逐 token 生成路径不同，接受率显著低于稠密模型上的经验值。后果是每个验证步里大量位置被拒绝、截断，KV cache 只追加了很短的前缀，而验证前向的算力已经花出去了。负载配方上这表现为“加速比随并发上升而下降”——并发越高，路由偏斜越严重，α 越低，分子越小。</p>\n<p><strong>崩法三：KV 追加与截断交错，page table 不一致。</strong>被拒绝位置要用目标分布重采样一个 token，KV 按接受长度批量追加而非逐 token 追加。若 page 归还与批量追加的处理顺序不当，KV cache 的逻辑长度与 page table 记录不一致，输出分布出现偏差。这类故障不体现在吞吐上，而是体现在输出质量的静默劣化——最难在负载配方阶段发现，只能靠批量追加路径的原子性设计来防。</p>\n<p>三种崩法的共同点是：它们都不在“平均吞吐”指标上暴露，而是在 TPOT 的尾部分布、接受率的并发斜率、以及输出一致性上暴露。负载配方的验收标准因此不能只看吞吐，必须同时看<strong>TPOT P99 随并发的斜率</strong>与<strong>接受率随 γ 的衰减曲线</strong>。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-23\">二十三 · 配方表：把请求形态映射到参数</h3>\n<p>把上述判断落成一张可执行的配方表，按请求形态分档给出参数取向。表中不填具体数值，因为材料未给出 γ、批大小与 SLO 的具体数字，只给出定性关系；工程上应以实测曲线填充每一格。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>长度分布特征</th><th>并发取向</th><th>γ 取向</th><th>主要风险</th></tr></thead><tbody>\n<tr><td>在线对话，短 prompt 长输出</td><td>输出中位数高、P99/中位数比小</td><td>按 $B\\times\\gamma$ 反推压低并发</td><td>取专家容量允许的上限</td><td>热点专家溢出</td></tr>\n<tr><td>代码补全，极短输出</td><td>输出长度集中在数十 token</td><td>可保持较高并发</td><td>取小值，避免验证批次空转</td><td>短请求提前终止，γ 利用率低</td></tr>\n<tr><td>批量离线推理</td><td>长度分布宽、无 TPOT 约束</td><td>大并发、大批</td><td>不优先，收益被吞吐目标稀释</td><td>路由偏斜在大批下更严重</td></tr>\n<tr><td>重尾混合流量</td><td>P99 远高于中位数</td><td>按分位切分，长请求单独成批</td><td>长请求档取大值，短请求档取小值</td><td>统一 γ 导致短请求浪费验证算力</td></tr>\n</tbody></table>\n<p>这张表的用法是：先按输出长度分布把流量切档，再对每档独立标定 γ 与并发，而不是全局一个 γ。混合流量下统一 γ 是最常见的配方错误——短请求档被长请求档的 γ 拖累，验证批次里塞满注定被截断的候选，分子没涨、分母照涨。</p>\n<p>具体例子：一个同时承载对话与代码补全的服务，若全局 γ=4，代码补全请求平均只输出 40 token，验证步里大部分位置在第二个候选就被拒绝，$\\mathbb{E}[\\text{tokens/step}]$ 实际只有 1.3 左右，而验证批次仍是 4 倍膨胀，加速比低于 1。按档切成 γ=1（等价关闭）与 γ=4 后，补全档回到普通 decode 的带宽受限基线，对话档拿到完整收益。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-24\">二十四 · 与容量规划的接口：并发上限怎么反推</h3>\n<p>负载配方最终要交给容量规划一个数：在给定硬件档位与并行拓扑下，这个负载能承载多少并发。投机解码把这个数改写了两次。第一次是显存侧：验证批次的激活缓冲、路由中间结果、专家分组临时空间按 γ 倍膨胀，KV cache 则因批量追加而碎片更少、有效容量略升。第二次是时延侧：TPOT 不再由单 token 的权重读取决定，而由“γ 个 token 的验证前向 + draft 的 γ 次前向”共同决定，且验证前向的时延随路由偏斜程度波动。</p>\n<p>反推的伪代码思路是：给定目标 TPOT SLO，先在关闭投机下测出单步时延与批大小的关系曲线；再在开启投机、固定 γ 下测出验证前向时延随 $B\\times\\gamma$ 的曲线；两条曲线的交点给出该 γ 下的最大并发。若交点处的并发低于业务需求，则降 γ 重测，直到并发满足或 γ 降到 1（即放弃投机）。这个循环的收敛条件是<strong>专家容量约束先于显存约束触发</strong>——一旦验证批次开始触发专家溢出，曲线出现拐点，交点必然落在拐点左侧。</p>\n<p>代价侧的量化要落到三个量上：单步验证前向的时延（含 draft 的 γ 次前向）、验证批次的激活显存峰值、以及路由偏斜导致的专家分组临时空间峰值。三者中任何一个先到顶，并发上限就被钉死。功耗维度上，投机解码把“多次小前向”换成“一次大前向”，单位 token 的能量效率通常改善，但 draft 模型的常驻计算是纯开销，在低并发下会拉低整体能效——这也是为什么负载配方把“并发是否足够高”作为是否开启投机的前置判断。</p>\n<p>具体例子：某部署在关闭投机时单卡可承载并发 48、TPOT 达标；开启 γ=3 后，验证批次等效 144 token，专家分组临时空间先于显存触顶，实测最大并发降到 14，TPOT 反而因验证前向排队而恶化。此时正确的动作不是继续调 γ，而是回到“并发是否够高”的前置判断：14 并发下 draft 的常驻开销摊不薄，投机在该负载上不成立。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-25\">二十五 · 负载不对时的工程判断：什么时候该关掉它</h3>\n<p>负载配方的最后一条是退出条件。投机解码在 MoE 上不是无条件正确的优化，它在三类负载上应当被关闭或降级：输出极短且长度方差小的请求（验证批次空转）、并发低到 draft 开销摊不薄的服务（分母里的 $c_{\\text{draft}}$ 占比过高）、以及路由分布本身高度集中、热点专家在普通 decode 下已接近容量上限的模型（γ 膨胀直接击穿）。</p>\n<p>判断依据不是单一指标，而是一组联立条件：接受率 α 在目标 γ 下是否显著高于 $1/\\gamma$ 的量级（否则分子涨不动）、验证批次 $B\\times\\gamma$ 是否落在专家容量拐点左侧（否则分母非线性上升）、以及 TPOT P99 随并发的斜率是否仍为负（否则加并发不再换吞吐）。三者任一不满足，就应把 γ 降到 1 并回到普通 decode 的带宽受限基线——那条基线虽然慢，但时延可预测、无 draft 常驻开销、无路由偏斜放大。</p>\n<p>落在具体机制上：关闭投机后，KV cache 回到逐 token 追加，page table 的一致性风险随之消失；专家分组回到常规批大小的容量标定，热点专家的尖峰被抹平；TPOT 重新由单 token 权重读取主导，容量规划的曲线回到单调。这不是退步，而是把负载配方与算法适用边界对齐——投机解码的 2–3 倍加速只在“带宽受限 + 并发足够 + 路由不过度偏斜”三者同时成立时才兑现，负载配方的工作就是判断这三者是否同时成立，并在不成立时果断退出。</p>\n<h3 id=\"alg-spec-decode-moe-sec-26\">二十六 · 硬件档位与并行拓扑的确定顺序</h3>\n<p>部署 MoE 投机解码时，先定拓扑再定卡型，顺序反了会锁死后续所有参数。原因是验证前向的批形状由 γ 决定，而 γ 的上限由专家容量与权重读取带宽共同约束，这两个约束都随并行切分方式变化。工程上的做法是：先按目标 MoE 的专家总数与单卡可容纳的专家权重份额确定 EP 组大小，再在该组内确定 TP 与 DP 的组合，最后用 draft 模型的显存占用去校验剩余空间。</p>\n<p>具体机制上，验证阶段一次并行处理 γ 个 token，路由按 token 独立计算，因此每个专家在验证批次内收到的 token 数是一个随机变量。若 EP 组内有 $E$ 个专家、验证批次为 $B_v$、路由为 top-$k$，则单个专家期望负载为 $B_v k/E$，而其容量上限通常按期望负载乘以一个容量因子设定。γ 增大时 $B_v$ 线性膨胀，负载的方差随之放大，热点专家溢出的概率上升。这就是为什么拓扑必须先固定 EP 组大小：EP 组越大，$E$ 越大，单专家期望负载越低，γ 的可标定上限越高。</p>\n<div class=\"formula\">$$B_v \\approx B_{\\text{req}}\\cdot\\gamma,\\qquad \\lambda_e=\\frac{B_v k}{E},\\qquad \\text{overflow}\\propto \\mathrm{Var}(\\lambda_e)/\\lambda_e$$</div>\n<p>系统代价落在三个地方。其一，EP 组跨节点时，验证阶段的 All-to-All 通信量与 $B_v$ 成正比，γ 翻倍则 dispatch 与 combine 的字节数翻倍，NVLink 域内的带宽占用随之上升；其二，draft 模型常驻显存，在 EP 切分下每个 rank 都要放一份完整的 draft 权重（稠密小模型无法按专家切），这部分显存不参与 EP 分摊，直接压缩了可用于 KV cache 与专家权重的预算；其三，功耗上验证前向是短时高占空比的算力爆发，而 decode 间隙是带宽受限的低占空比，电源与散热设计要按验证峰值而非平均负载取值。</p>\n<p>一个具体例子：在单机 8 卡 NVLink 域内跑一个专家数较多的 MoE，若把 EP 组设为 8、TP 设为 1，则每卡承载 $E/8$ 个专家，验证批次在组内做一次 All-to-All 即可完成 dispatch；若把 EP 组扩到跨机 16 卡，单专家期望负载减半，γ 可以标定得更大，但每次验证要多一跳跨机 All-to-All，TPOT 的通信项变重。判断依据是：当 γ 带来的带宽摊薄收益大于跨机通信增量时选大 EP 组，否则留在单机域内。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-27\">二十七 · 量化方案的组合约束</h3>\n<p>量化方案在投机解码里不是单点选择，而是三处独立决策的耦合：目标 MoE 的专家权重精度、验证阶段激活的精度、以及 draft 模型的精度。三者可以不同，但必须满足一条硬约束——拒绝采样要求 draft 分布 $q$ 与目标分布 $p$ 在同一数值语义下比较，若 draft 用低精度而目标用高精度，$q$ 的系统性偏差会直接压低接受率。</p>\n<p>机制上，验证前向的 GEMM 形状是 $(\\gamma, d)$ 乘专家权重，属于典型的瘦高矩阵乘，权重读取占主导。把专家权重压到 NVFP4 这类微缩放格式，权重字节数下降，单次验证的权重读取时间随之下降，这正是投机解码摊薄带宽的乘数效应所在：原本一次读取服务 1 个 token，现在服务 γ 个 token，权重越小，摊薄后的每 token 带宽成本越低。但激活侧若也压到低精度，$p_i$ 的数值噪声会改变接受判定的边界，尤其在 $p_i/q_i$ 接近 1 的位置，微小扰动会翻转接受结果。</p>\n<div class=\"formula\">$$a_i=\\min\\!\\left(1,\\frac{p_i}{q_i}\\right)\\;\\Rightarrow\\;\\mathbb{E}[a]\\approx 1-\\tfrac{1}{2}\\mathbb{E}\\!\\left[\\left|\\frac{\\Delta p}{p}-\\frac{\\Delta q}{q}\\right|\\right]$$</div>\n<p>代价方面：低精度专家权重降低显存占用与读取带宽，直接改善 TPOT；但若 draft 与目标精度不一致，接受率下降会使有效 tokens/step 变小，验证算力被拒绝位置浪费，等效吞吐反而下降。工程判断是让 draft 与目标共享同一套量化语义（同格式、同缩放粒度），把精度差异留在不影响比值判定的位置。</p>\n<p>具体例子：目标 MoE 专家权重用 NVFP4 微缩放、激活保持较高精度以稳定 $p_i$；draft 若是 MoE 自身的轻量头，则轻量头必须与主模型同精度导出，否则 $q$ 的偏差会在高接受概率区间制造系统性拒绝。若 draft 是小稠密模型，则它可独立量化，但要用一小批校准请求实测接受率，确认没有因精度错配导致的接受率塌陷。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-28\">二十八 · KV 策略：按接受长度批量追加</h3>\n<p>投机解码的 KV 管理与常规 decode 的根本差别在于写入是批量的、长度是随机的。一次验证产生 $\\ell$ 个被接受 token（$\\ell\\le\\gamma$，全接受时再加一个 bonus token），KV 必须按 $\\ell$ 一次性追加，而不是逐 token 追加。逐 token 追加会在每个位置触发一次 page 分配与元数据更新，在 γ 较大时把调度器压成瓶颈。</p>\n<p>机制上，验证前向需要为 γ 个候选位置预留 KV 槽位（因为验证时要写入这 γ 个位置的 K/V 才能算出 $p_i$），验证结束后只有前 $\\ell$ 个位置有效，其余 $\\gamma-\\ell$ 个位置必须归还。这就要求 KV 管理器支持“预留—提交—回滚”三段式：预留时按 γ 申请 page，提交时按 $\\ell$ 固化并更新序列长度，回滚时把尾部 $\\gamma-\\ell$ 个 page 标记为空闲但不立即重用（避免与在途验证批次冲突）。</p>\n<div class=\"formula\">$$\\text{page need}=\\left\\lceil \\frac{L_{\\text{seq}}+\\gamma}{P}\\right\\rceil-\\left\\lceil \\frac{L_{\\text{seq}}}{P}\\right\\rceil,\\qquad \\text{commit}=\\left\\lceil \\frac{L_{\\text{seq}}+\\ell}{P}\\right\\rceil$$</div>\n<p>系统代价集中在碎片与一致性两点。碎片方面，γ 预留但只提交 $\\ell$ 会造成尾部 page 的短暂占用，若 $\\ell$ 的分布偏斜（多数请求只接受 1–2 个 token），预留的 γ 个 page 大部分被回滚，page 池的有效利用率下降，长上下文请求更容易触发抢占。一致性方面，若回滚与下一轮预留交错，page table 的序列长度字段与实际有效 K/V 长度可能脱节，表现为输出分布偏移——这正是失败模式里提到的 KV 长度与 page table 不一致。</p>\n<p>具体例子：一个长上下文请求在验证后只接受了 1 个 token，尾部 $\\gamma-1$ 个 page 被回滚；若调度器立即把这些 page 分配给另一个请求，而前一个请求的验证批次尚未完全退出，就会出现同一 page 被两条序列引用的窗口。稳妥做法是给回滚 page 加一个短生命周期标记，等验证批次确认退出后再入空闲池，代价是 page 池瞬时容量需求上升约一个 γ 的量级。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-29\">二十九 · 调度参数：γ、批大小与容量因子的联动</h3>\n<p>调度层要同时管三个互相拉扯的参数：γ、验证批大小上限、专家容量因子。它们不是独立可调的，任何两个固定后第三个就被约束。工程上推荐的标定顺序是：先按 SLO 的 TPOT 目标反推单步允许的验证前向时间，再由该时间与专家权重读取带宽算出 γ 的上限，最后用容量因子去吸收路由方差。</p>\n<p>机制上，验证前向的时间近似为权重读取时间与算力时间之和，而权重读取时间与 γ 基本无关（权重只读一次），算力时间随 γ 线性增长。因此存在一个 γ 使总时间最小化：γ 太小时带宽摊薄不足，γ 太大时算力项与路由溢出项反超。用前文的加速比公式看，分母里的 $\\gamma c_{\\text{draft}}/c_{\\text{target}}$ 就是 draft 开销随 γ 增长的项，分子 $\\mathbb{E}[\\text{tokens/step}]$ 随 γ 增长但受接受率 $\\alpha$ 饱和。</p>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)\\left(1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}\\right)}$$</div>\n<p>代价与判断：批大小上限要按 $B_{\\text{req}}\\cdot\\gamma$ 设定，而不是按 $B_{\\text{req}}$，否则验证批次会被调度器截断，γ 的实际生效值小于配置值，加速比达不到标定预期。容量因子若设得过紧，热点专家溢出会迫使验证前向拆分或排队，单步时间反而拉长；设得过松则专家权重分块变大，显存占用上升，挤压 KV 预算。功耗维度上，γ 越大验证前向的算力占空比越高，单步能耗上升，但在 TPOT 约束下单位 token 能耗可能下降，需按吞吐目标而非单步能耗取舍。</p>\n<p>具体例子：在线低延迟服务里，若 TPOT 目标较紧，把 γ 标定在使验证前向恰好填满一次权重读取窗口的值，容量因子取略高于路由期望负载的水平以吸收方差；当监控到热点专家溢出率上升时，优先降 γ 而不是放宽容量因子，因为放宽容量因子会增加显存占用并压缩 KV，而降 γ 只损失带宽摊薄收益。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-30\">三十 · 可复现的配置思路</h3>\n<p>把上述四节收束成一条可复现的标定流程，每一步都有明确的观测量与停止条件，不依赖猜测。</p>\n<ul>\n<li>第一步，固定 EP 组与 TP 组合，使单专家期望负载 $\\lambda_e=B_v k/E$ 在目标 γ 下不超过容量因子的设定值；用一次合成请求压测确认 All-to-All 字节数与 TPOT 的通信项占比。</li>\n<li>第二步，统一 draft 与目标的量化语义，导出 draft 权重后跑一小批真实请求，测接受率 $\\alpha$ 与接受长度分布；若 $\\alpha$ 明显低于同规模稠密模型的预期，先查精度错配再查路由偏好差异。</li>\n<li>第三步，按接受长度分布设定 KV 预留策略：预留按 γ、提交按 $\\ell$、回滚加生命周期标记；观测 page 池有效利用率与抢占率，若碎片导致抢占上升则缩短回滚标记窗口。</li>\n<li>第四步，用加速比公式做 γ 扫描，横轴 γ、纵轴实测 tokens/step 与单步时间，找到单步时间最小值对应的 γ，再向下取一档留出路由方差余量。</li>\n<li>第五步，把批大小上限设为 $B_{\\text{req}}\\cdot\\gamma$ 并验证调度器不截断；监控专家溢出率、接受率、page 利用率三个指标，任一恶化即回到对应步骤调整。</li>\n</ul>\n<p>这套流程的关键判断是：γ 的最终取值由专家容量与带宽上限共同标定，而不是由 draft 模型的提议速度单独决定。当 draft 很快但 γ 受容量约束时，提高 draft 质量（提升 $\\alpha$）比增大 γ 更有效，因为 $\\alpha$ 提升直接抬高 $\\mathbb{E}[\\text{tokens/step}]$ 的饱和值而不增加验证批次。反之，当 $\\alpha$ 已高而带宽仍是瓶颈时，才值得在容量因子允许的范围内推高 γ。</p>\n<p>最后落在工程判断上：MoE 投机解码的部署配方本质是把“权重读取一次服务多个 token”这件事做成可标定的闭环——拓扑定容量、量化定带宽乘数、KV 定写入粒度、调度定 γ 上限，四者中任一环节的余量不足都会让 2–3 倍的加速区间收窄甚至翻负。可复现的标志不是参数表，而是五个观测指标（$\\lambda_e$、$\\alpha$、page 利用率、溢出率、单步时间）在 γ 扫描曲线上同时可解释。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-31\">三十一 · 边界标定：γ、专家容量与 KV 追加的一致性约束</h3>\n<p>这套配方真正需要标定的不是硬件档位本身，而是 γ 与专家容量之间的耦合关系。验证阶段一次并行前向 γ 个 draft token，等价于把有效批大小从常规 decode 的 B 放大到 B·γ 量级；而 MoE 路由按 token 独立计算，热点专家收到的 token 数近似服从超几何分布，其期望负载为 λ = B·γ·(k/E)，其中 k 为每 token 激活专家数、E 为专家总数。当 λ 接近单专家容量上限时，路由分布偏斜会让少数专家溢出，验证前向被迫拆分或排队，加速比按 $$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$ 中的分母项迅速恶化——γ 增大带来的 tokens/step 收益被 c_draft 与拆分开销吃掉，甚至转为负收益。工程判断是：γ 的上界应由“最热专家负载不超容量”反解，而不是由接受率或带宽余量单独决定。</p>\n<p>失效条件集中在两处。其一是路由偏好不一致：draft 模型（小稠密模型或 MoE 自身轻量头）对候选 token 的专家选择与目标 MoE 逐 token 生成路径不同，导致接受率显著低于稠密模型投机解码的预期，验证算力大量消耗在被拒绝位置上；此时应下调 γ 或改用与目标模型共享路由偏好的轻量头，而不是继续加大 γ 赌接受率。其二是 KV 一致性：被接受 token 按长度批量追加、被拒绝位置用目标分布重采样一个 token，若 page 归还与批量追加交错执行，page table 与实际序列长度会出现短暂不一致，输出分布随之偏移。配方要求追加与截断在同一调度步内原子完成，先截断到接受前缀长度，再批量追加，最后才归还多余 page。</p>\n<table class=\"mini\"><thead><tr><th>参数</th><th>标定依据</th><th>越界后的系统代价</th></tr></thead><tbody><tr><td>γ</td><td>最热专家负载 ≤ 容量</td><td>验证批次膨胀、专家溢出、TPOT 抖动</td></tr><tr><td>draft 模型</td><td>额外显存与计算预算</td><td>挤占 KV page 池，降低并发上限</td></tr><tr><td>KV 追加粒度</td><td>接受长度分布</td><td>碎片化与 page table 不一致</td></tr></tbody></table>\n<p>可复现的配置思路是：先固定 draft 模型与量化方案，测出接受长度分布与热点专家负载曲线；再以专家容量为约束扫描 γ，取 TPOT 满足 SLO 且最热专家不溢出的最大 γ；最后把 KV 追加做成按接受长度的批量事务，并在调度器中为验证批次预留独立的专家容量配额，避免与常规 decode 请求争抢同一批热点专家。带宽受限场景下 2–3 倍加速的前提，正是 γ 停在这个容量边界之内。</p>\n<h3 id=\"alg-spec-decode-moe-sec-32\">三十二 · 验证批膨胀：γ 把 decode 批从“小”推到“大”</h3>\n<p>投机解码在 MoE 上的第一笔系统代价不是显存，而是批大小的非线性放大。普通 decode 每步每请求只推进 1 个 token，连续批处理下批大小由并发请求数决定；验证阶段一次并行处理 γ 个候选 token，等效批大小变成“并发请求数 × γ”。这意味着调度器原本按 decode 常规批大小标定的显存预算、专家容量因子、SM 占用全部失配。γ 不是免费参数，它直接改写批调度器的输入。</p>\n<p>把接受长度记为随机变量，单步产出 token 数的期望由几何式给出：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}]=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>其中 α 为逐位置接受率，c_draft 与 c_target 分别为 draft 与目标 MoE 的单 token 代价。这个式子的工程含义是：γ 增大时分子趋近 1/(1−α) 饱和，分母却随 γ 线性增长。当 c_draft/c_target 不可忽略（MoE 自身轻量头做 draft 时尤其如此），γ 超过某个拐点后加速比单调下降。拐点位置由 α 与代价比共同决定，而不是由“γ 越大越好”的直觉决定。</p>\n<p>具体例子：某在线低延迟 decode 服务并发 64 请求，常规 decode 批为 64；取 γ=8 后验证批膨胀到 512。这 512 个 token 在 MoE 层按 token 独立路由，路由分布随 draft token 变化而偏斜，热点专家在容量因子约束下溢出，验证前向被迫拆分为多个 micro-batch 串行执行。拆分带来的 kernel 启动与同步开销直接吃掉并行验证摊薄权重读取的收益，加速比从正转负。这就是“规模上去以后哪里先崩”的第一个答案：崩在批调度器与专家容量因子的匹配上，而不是崩在算力上。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-33\">三十三 · 带宽账：摊薄的是权重读取，不是 KV 读取</h3>\n<p>MoE decode 的时延瓶颈是权重读取带宽：每 token 只激活少量专家，算力闲置而权重必须从 HBM 搬进 SM。投机解码的收益来源正是把这批权重读取摊到 γ 个 token 上——验证阶段一次前向读一遍被激活的专家权重，产出 γ 个位置的概率。但要注意，摊薄只作用于专家权重，KV cache 的读取随 γ 线性增长：验证时要为 γ 个位置各读一份历史 KV，注意力部分的带宽开销按 γ 放大。</p>\n<p>因此单步带宽账可写成两项之和：专家权重读取约等于“被激活专家集合的字节数”（与 γ 弱相关，只要 γ 个 token 命中同一批专家），KV 读取约等于“γ × 每 token 注意力 KV 字节数”（与 γ 强线性相关）。当 γ 增大，前者被摊薄得越来越薄，后者却线性上升，最终 KV 带宽项反超专家权重项，投机解码失去带宽套利空间。这个交叉点是 γ 标定的硬上界之一，且随上下文长度前移：长上下文场景下 KV 读取本来就占主导，γ 的可用窗口更窄。</p>\n<p>工程判断：γ 应按“专家权重读取字节数 / 单 token KV 读取字节数”的比值来定，而不是按经验常数。上下文越长、KV 越重，γ 应越小；专家越宽、激活越稀疏，γ 可越大。这与稠密模型投机解码的标定逻辑不同——稠密模型没有专家权重读取这一项，γ 主要受 draft 代价与接受率约束。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-34\">三十四 · 通信账：验证批放大 All-to-All 的消息数与不均衡度</h3>\n<p>专家并行部署下，MoE 层每个 token 的路由结果决定它要发往哪些 rank，All-to-All 的通信量正比于 token 数乘以每 token 的副本数（top-k）。验证阶段 token 数变成 γ 倍，All-to-All 的消息数同比例放大。更麻烦的是不均衡：γ 个 draft token 的路由由 draft 模型隐式决定，其专家选择与逐 token 生成路径不同，路由分布更容易偏斜，热点 rank 的发送缓冲与接收缓冲被撑大，通信从“带宽受限”转为“最慢 rank 受限”。</p>\n<p>伪代码层面的代价可以这样估算单步通信下界：</p>\n<div class=\"formula\">$$T_{\\text{comm}}\\gtrsim \\frac{\\gamma\\cdot B\\cdot k\\cdot s}{W_{\\text{link}}}+\\text{max-rank skew}$$</div>\n<p>其中 B 为并发请求数，k 为每 token 路由副本数，s 为单副本元素字节数，W_link 为链路有效带宽，末项为最慢 rank 相对均值的偏移。γ 增大时第一项线性增长，第二项因路由偏斜而放大。NVLink 5 与 NCCL 的低延迟集合通信能压住第一项，但压不住第二项——偏斜是路由分布的性质，不是链路的性质。</p>\n<p>具体例子：NVL72 域内专家并行，验证批 512 token、top-k=2、每副本按 FP8 计，单步 All-to-All 需搬运的消息量随 γ 翻倍；若某热点专家所在 rank 接收量超出均值数倍，该 rank 的接收缓冲成为瓶颈，其余 rank 空等，单步时延由最慢 rank 决定。此时增加 γ 不会提高吞吐，只会拉长尾延迟。规模上去以后第二个崩点：崩在 All-to-All 的偏斜尾部，而不是崩在总带宽。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-35\">三十五 · 显存与功耗：draft 模型的固定开销与验证激活值的瞬时峰值</h3>\n<p>draft 模型无论多小都要常驻显存：权重、它自己的 KV cache、以及为并行提议 γ 个 token 所需的中间激活。这部分显存与并发请求数成正比，且与目标 MoE 的专家权重、分页 KV 争夺同一池子。MoE 部署本就把大量显存让给专家权重，draft 模型的固定占用直接压缩了可用于 KV 分页的余量，进而压低可支撑的并发数——这是一个用并发换单请求时延的交易，容量规划时必须显式计入。</p>\n<p>验证阶段的激活值峰值是另一笔瞬时开销。γ 个位置并行前向，中间激活按 γ 放大，且 MoE 层的路由中间缓冲（dispatch/combine 的暂存）也按 γ 放大。峰值显存不体现在稳态占用上，却决定了单步能否不拆分地跑完；一旦峰值越过余量，运行时被迫拆分验证批，前面算的加速比全部作废。功耗侧同理：验证阶段算力利用率被拉高，SM 从“等权重”转为“真计算”，瞬时功耗抬升，在功耗封顶的机柜里可能触发降频，反过来拉长单步时延。</p>\n<p>工程判断：draft 模型的显存占用应按“占目标 MoE 可用显存的比例”设上限，而不是按参数量绝对值；验证激活峰值应作为 γ 标定的第三个约束（前两个是带宽交叉点与专家容量），在长上下文、高并发下先于带宽约束生效。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-36\">三十六 · 接受率与尾延迟：路由不一致如何把算力浪费在拒绝位置</h3>\n<p>MoE 投机解码的接受率系统性低于稠密模型预期，原因在路由：draft token 的专家选择与逐 token 生成路径不同，draft 模型给出的 q 与目标 MoE 在该上下文下的 p 在专家层面就产生了分布偏移，逐位置接受概率 a_i = min(1, p_i/q_i) 因此更容易落到拒绝区间。被拒绝的位置不是“没产出”，而是“产出了但被丢弃”——验证阶段为这些位置付出的专家权重读取、All-to-All 通信、KV 读取全部沉没。</p>\n<p>把浪费量化：单步有效 token 数为接受长度，验证算力按 γ 计，浪费比例约为 1 − E[接受长度]/γ。α 偏低时这个比例很高，γ 越大浪费的绝对量越大。尾延迟的角度更尖锐：P99 请求的接受长度分布尾部短，意味着这些请求几乎每个验证步都只接受 1–2 个 token，却付了 γ 倍的验证代价，TPOT 反而比不开投机更差。SLO 以 TPOT 为主时，尾延迟恶化直接表现为 SLO 违约率上升，而平均吞吐可能仍在改善——这是最容易被监控平均值掩盖的崩点。</p>\n<p>具体例子：某请求在长上下文下 draft 模型连续给出与目标 MoE 路由偏好不符的候选，逐位置接受率降到很低，γ=8 的验证步只接受 1 个 token，单步时延却是普通 decode 的数倍；该请求的 TPOT 尾部被拉长，触发 TPOT SLO 告警。缓解手段不是调大 γ，而是按路由一致性筛选 draft 候选、或在接受率低于阈值时动态退回普通 decode——把 γ 变成按请求、按上下文自适应的量。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-37\">三十七 · 规模上去先崩哪里：三个约束的先后次序</h3>\n<p>把上述代价放在同一张账上，规模扩大时崩溃点的次序是可以排序的。第一崩点是专家容量：验证批膨胀使路由偏斜放大，热点专家溢出导致验证前向拆分，这是最先发生的，因为它由容量因子这一硬阈值触发，不随带宽余量缓解。第二崩点是 All-to-All 偏斜尾部：即使容量因子放宽，最慢 rank 的接收缓冲仍决定单步时延，尾延迟随规模非线性恶化。第三崩点是 KV 带宽交叉：上下文变长后 KV 读取项反超专家权重项，投机解码的带宽套利消失，γ 的可用窗口收窄至零。</p>\n<p>这三者共同决定 γ 的标定不是单参数优化，而是三约束下的可行域求解：γ 上限由专家容量与路由偏斜给出，由 All-to-All 最慢 rank 收紧，再由 KV 带宽交叉点最终封顶。工程上应把 γ 做成运行时自适应量：按当前批的专家负载分布、All-to-All 缓冲水位、上下文长度动态收缩，在接受率跌破阈值时退回普通 decode。KV 按接受长度批量追加、page 归还与截断需与批量追加原子化处理，否则长度与 page table 不一致会在高并发下放大为输出偏差——这是规模上去后最隐蔽的崩点，因为它不表现为时延，而表现为正确性。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-38\">三十八 · 验证批次膨胀与专家容量：MoE 投机解码先崩在哪里</h3>\n<p>稠密模型投机解码的瓶颈通常在 draft 侧，MoE 的瓶颈却前移到验证侧：γ 个候选 token 一次性进入目标 MoE 前向，等效批大小被放大 γ 倍，而 MoE 路由按 token 独立计算，γ 个位置命中的专家集合互不相同。加速比的解析式已经把代价写清楚了：<div class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>其中 $c_{\\text{draft}}$ 与 $c_{\\text{target}}$ 分别是 draft 与目标模型单步的代价。分母随 γ 线性增长，分子却由接受率 $\\alpha$ 饱和于 $1/(1-\\alpha)$；一旦 $\\gamma c_{\\text{draft}}/c_{\\text{target}}$ 的增速超过期望接受 token 数的增速，加速比掉头向下。MoE 上这个拐点来得更早，因为 $c_{\\text{target}}$ 在验证阶段不是常数——路由偏斜会把它抬高。</p>\n<p>具体机制是专家容量溢出。验证批次里 γ 个 token 若集中命中少数热点专家，这些专家在单次前向中要处理的 token 数超出容量上限，验证前向被迫拆分、重排或排队，原本“权重只读一次”的带宽收益被额外的调度与重放吃掉。这与逐 token decode 的负载形态完全不同：后者每步只有一个 token，专家分布天然平滑；验证批次把 γ 个 token 的专家选择叠加，方差被放大。工程上 γ 必须按专家容量与带宽上限联合标定，而不是按稠密模型的经验值取。一个可操作的判据是：验证批次中最大专家负载与平均负载之比超过容量余量时，就该收缩 γ 或对 draft token 做路由感知的截断。</p>\n<p>第二类失效来自路由偏好不一致。draft 模型（小稠密模型或 MoE 自身的轻量头）给出的候选 token 分布与目标 MoE 逐 token 生成路径的专家选择不同，draft token 命中的专家往往不是目标模型在该上下文下会走的专家，逐位置接受概率 $a_i=\\min(1,p_i/q_i)$ 因此系统性偏低，接受率显著低于稠密模型预期。被拒绝的位置仍消耗了完整验证算力，验证前向的算力被大量拒绝位置浪费——这正是 MoE 投机解码“省带宽不省算力”的代价结构。规模上去以后，先崩的通常不是显存而是尾延迟：验证批次膨胀推高单步 TPOT 的方差，专家溢出引发的拆分让 P99 尾延迟脱离均值，SLO 以 TPOT 为主时这一项最先击穿预算。</p>\n<table class=\"mini\"><thead><tr><th>规模维度</th><th>先崩的资源</th><th>触发条件</th></tr></thead><tbody><tr><td>γ 增大</td><td>专家容量 / 尾延迟</td><td>热点专家负载超容量，验证前向拆分</td></tr><tr><td>并发批增大</td><td>显存（draft + KV）</td><td>draft 模型常驻显存与按接受长度批量追加的 KV 叠加</td></tr><tr><td>路由偏斜加剧</td><td>有效算力（接受率）</td><td>draft 与目标专家选择分歧扩大</td></tr></tbody></table>\n<p>还有一处容易被忽略的代价在 KV 管理：按接受长度批量追加而非逐 token 追加，减少了碎片，但拒绝位置的重采样与截断必须和 page 归还严格对齐，否则 page table 与逻辑长度不一致，输出分布出现偏差——这是无偏性保证在系统层的漏洞，而非算法层的。功耗维度上，MoE decode 本就处于算力闲置、带宽受限的低利用率区间，投机解码把闲置算力换成验证批次，单位 token 能耗未必下降；γ 过大时验证前向的算力浪费反而推高每 token 能耗。因此这套方案的适用边界是带宽受限且专家负载可控的在线低延迟 decode：2–3 倍加速成立的前提是 γ 与专家容量、draft 开销三者同时被标定在拐点之内。</p>\n<h3 id=\"alg-spec-decode-moe-sec-39\">三十九 · 精度失配：接受率塌陷的三种来源</h3>\n<p>MoE 投机解码的精度问题不是数值溢出，而是接受率与预期系统性偏离。逐位置接受概率为 <span class=\"formula\">$$a_i = \\min\\left(1, \\frac{p_i}{q_i}\\right)$$</span>，其中 $p_i$ 是目标 MoE 对第 $i$ 个候选 token 的概率、$q_i$ 是 draft 给出的概率。这条公式在稠密模型上表现良好，因为 draft 与 target 共享同一套参数分布族；在 MoE 上则出现三种失配。第一种是路由失配：draft token 命中的专家集合与目标 MoE 逐 token 生成路径的专家集合不同，$p_i$ 是在一组未激活专家上算出的条件概率，与 $q_i$ 的支撑集错位，$p_i/q_i$ 的比值方差远大于稠密情形。第二种是 draft 头失配：当 draft 是 MoE 自身的轻量头时，它只看到部分层输出，对长尾 token 的 $q_i$ 估计偏低，导致 $a_i$ 被系统性压低。第三种是验证批次内的路由漂移：γ 个候选 token 一次并行前向，路由按 token 独立计算，热点专家在验证批次中被集中命中，容量因子截断使部分 token 的 $p_i$ 实际来自被丢弃后的重归一化分布，与逐 token 路径不一致。</p>\n<p>诊断这三类失配不能只看整体接受率。工程上按位置分桶统计 $a_i$：位置 0 的接受率反映 draft 首 token 质量，位置 $k$ 的接受率衰减曲线反映路由漂移强度。若衰减在 $k\\ge 3$ 处陡降，说明验证批次膨胀后专家容量开始截断；若位置 0 就低，说明 draft 头本身与目标分布错位。另一个指标是 $p_i/q_i$ 的比值直方图，路由失配会呈现双峰——一部分 token 比值接近 1，另一部分被压到接近 0，而不是稠密模型上的单峰集中。代价上，接受率每下降 0.1，验证阶段被拒绝位置浪费的算力按 γ 比例放大，带宽摊薄收益被抵消；当接受率低于约 1/(1+γ·c_draft/c_target) 的盈亏平衡点时，加速比转负。</p>\n<p>具体例子：一个 8 专家激活的 MoE 在 γ=4 时，位置 2、3 的接受率从位置 0 的 0.8 量级跌到 0.3 量级，比值直方图呈双峰，定位为热点专家容量截断而非 draft 质量问题。回滚手段是先把 γ 降到 2 观察衰减曲线是否变平，再决定是调容量因子还是换 draft 头。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-40\">四十 · OOM：draft 显存与验证批次的乘性占用</h3>\n<p>OOM 在 MoE 投机解码里有两个独立来源，必须分开归因。其一是 draft 模型的常驻显存：小稠密 draft 或 MoE 轻量头都要额外占一份权重与一份 KV，且这份占用不随批大小伸缩，属于固定开销。其二是验证批次的瞬时激活：γ 个候选 token 并行前向使有效批大小变为 $B\\cdot\\gamma$，MoE 的中间激活、路由 logits、专家分组缓冲都按这个乘性因子膨胀。分页 KV 与专家权重共存显存时，KV 按接受长度批量追加而非逐 token 追加，追加瞬间的 page 需求是尖峰而非均值，若按平均接受长度做容量规划，尖峰时刻就会 OOM。</p>\n<p>诊断要区分“稳态 OOM”与“尖峰 OOM”。稳态 OOM 在固定批大小下可复现，看的是 draft 常驻加验证激活的基线；尖峰 OOM 只在接受长度分布的长尾出现，表现为偶发、与请求内容相关。监控上采集两个量：验证前向前的空闲显存，以及 KV 批量追加前后的 page 占用差。若空闲显存在追加前充足、追加后触顶，则是 page 归还与批量追加交错导致的碎片，而非真实容量不足。公式上，验证批次显存需求近似正比于 $B\\cdot\\gamma\\cdot(\\text{激活/ token})$，γ 翻倍即激活翻倍，而 draft 常驻不变，所以 OOM 归因的第一刀是看 γ 调整是否改变复现率。</p>\n<p>具体例子：批大小 32、γ=6 时稳态可跑，但长请求接受长度到 6 时追加 page 触发 OOM；把 γ 降到 4 后尖峰消失，说明是验证批次乘性膨胀而非 draft 常驻问题。回滚路径是先降 γ、再降批、最后才动 draft 模型规格，因为前两者是可逆的运行时旋钮，后者要重新标定接受率基线。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-41\">四十一 · 批抖动与路由不均：验证批次放大的负载偏斜</h3>\n<p>批抖动指相邻调度周期的有效批大小剧烈波动，根因是接受长度分布的长尾：一个请求接受 1 个 token 与接受 γ+1 个 token，对下一轮 KV 追加量和验证批次的影响差一个量级。连续批处理按 token 计费时，这种波动直接转化为 TPOT 的方差。MoE 把这个问题放大：验证批次内 γ 个 token 的路由按 token 独立计算，热点专家在批内被集中命中，容量因子截断使部分 token 溢出到次优专家或排队，验证前向被迫拆分，尾延迟尖刺由此产生。</p>\n<p>诊断批抖动看两个分布而非均值：每步有效批大小的分布，以及每步热点专家命中数的分布。前者长尾说明接受长度方差大，后者长尾说明路由偏斜。工程判据是热点专家命中数超过容量因子的步占比，若这个占比随 γ 上升而单调上升，则批抖动的主因是验证批次膨胀而非请求到达过程。路由不均还有一个隐蔽形态：draft token 的专家选择与逐 token 生成不同，使验证阶段实际激活的专家集合比稳态 decode 更宽，All-to-All 调度量随之上升，通信成为尾延迟的新瓶颈。</p>\n<p>具体例子：γ=5 时热点专家命中数分布的 99 分位超过容量因子，验证前向拆分导致 TPOT 尖刺；把 γ 降到 3 并把容量因子按验证批次而非稳态 decode 标定后，尖刺消失。回滚顺序是先调容量因子匹配验证批次峰值，再降 γ，最后才考虑改路由策略——因为容量因子是可在线调整的，改路由要重跑接受率标定。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-42\">四十二 · 尾延迟尖刺：KV 截断与 page table 不一致</h3>\n<p>最危险的一类失败不是慢，而是错。被拒绝位置用目标分布重采样一个 token 时，KV cache 的处理是“截断到接受前缀再追加重采样 token”。若 page 归还与批量追加交错执行，page table 的长度记录与实际 KV 内容可能不一致：截断时归还的 page 被下一轮追加复用，而旧 page 的残留内容未清零，导致注意力读到跨请求的脏数据，输出分布出现偏差。这类偏差不会表现为接受率下降，而是表现为输出质量偶发劣化，且只在长请求、高并发时出现。</p>\n<p>诊断这类问题靠一致性校验而非性能指标：在每个验证周期后比对 page table 的逻辑长度与 KV 实际写入长度，以及被截断位置的 page 是否在归还队列中。另一个信号是重采样 token 的分布偏移——若重采样位置的输出熵异常低，说明它读到了不该读的 KV。尾延迟尖刺与这类错误常同源：page 归还与追加交错造成锁竞争或串行化，表现为周期性尖刺。</p>\n<p>具体例子：接受长度 2、拒绝位置 3 的请求在截断后归还 1 个 page，下一轮同批请求追加时复用了该 page 但未清零，注意力读到上一请求的残差，输出出现重复片段。回滚手段是关闭 page 复用直到清零逻辑上线，并把 KV 追加改为按接受长度整段批量追加、截断与归还分离到独立阶段，牺牲少量吞吐换一致性。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-43\">四十三 · 监控面与回滚阶梯</h3>\n<p>监控面按“先归因、再回滚”组织，四个维度各自对应一类失败。接受率维度：整体接受率、按位置分桶的 $a_i$、$p_i/q_i$ 比值直方图，用于定位精度失配。显存维度：验证前向空闲显存、KV 批量追加前后 page 占用差、draft 常驻占用，用于区分稳态与尖峰 OOM。负载维度：每步有效批大小分布、热点专家命中数分布、All-to-All 调度量，用于定位批抖动与路由不均。一致性维度：page table 逻辑长度与 KV 实际长度比对、重采样位置输出熵，用于捕捉 KV 截断错误。四个维度共享同一时间轴，任一维度异常时能立刻判断是 γ、容量因子、批大小还是 page 管理的问题。</p>\n<p>回滚阶梯按可逆性排序，每一步都有明确的触发条件。第一级：降 γ。触发条件是接受率衰减曲线在 $k\\ge 3$ 陡降，或热点专家命中数超容量因子的步占比上升。γ 是可在线调整的运行时旋钮，降 γ 直接缩小验证批次，代价是带宽摊薄收益下降。第二级：调容量因子匹配验证批次峰值，触发条件是路由不均但接受率正常，代价是稳态 decode 的专家利用率下降。第三级：降批大小，触发条件是尖峰 OOM 或批抖动长尾，代价是吞吐线性下降。第四级：关闭 page 复用并改为截断与归还分离，触发条件是一致性校验失败，代价是吞吐小幅下降换正确性。第五级：换 draft 模型或重标定 draft 头，触发条件是位置 0 接受率就低，这是唯一需要停机重跑标定的回滚。</p>\n<p>回滚的工程判断在于区分“收益抵消”与“正确性受损”。前四级都是性能与资源的权衡，可以在线执行并观察加速比是否回到正值；第五级涉及分布一致性，必须在离线标定后灰度上线。加速比公式 <span class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$</span> 给出盈亏平衡判据：当 $\\mathbb{E}[\\text{tokens/step}]$ 因接受率塌陷而降到 $1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}$ 以下时，任何 γ 都是负收益，此时回滚阶梯的第一级不是降 γ 而是先修接受率。监控面必须把 $\\mathbb{E}[\\text{tokens/step}]$ 与分母项同时上报，否则无法判断是 γ 过大还是接受率过低。</p>\n<p>具体机制落点是：把每次验证周期的 $\\mathbb{E}[\\text{tokens/step}]$、$\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}$、热点专家命中数、page table 一致性校验结果写进同一条结构化日志，回滚决策由这条日志的阈值触发而非人工巡检。γ 与容量因子的调整走配置热更新，page 复用开关走灰度，draft 替换走离线标定加灰度——三级回滚路径的响应时间依次递增，与失败模式的严重程度对齐。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-44\">四十四 · 当验证批次压垮路由：MoE 投机解码的失效边界与回滚判据</h3>\n<p>投机解码在 MoE 上的收益并非单调随 γ 增长。验证阶段一次并行处理 γ 个 token，等效批大小从 decode 常规的 B 膨胀到 B·(γ+1) 量级，而 MoE 路由按 token 独立计算，专家选择随 draft token 漂移，热点专家的 token 计数迅速越过容量上限。一旦某专家的验证队列超出其单次前向可承载的 token 数，验证前向被迫拆分或排队，原本\"一次权重读取摊到 γ 个 token\"的带宽优势被额外的专家权重重读抵消。用加速比公式判断边界：当 γ 增大使 c_draft 与验证拆分的重读代价同步上升，分母 1+γ·c_draft/c_target 的增长快于分子 E[tokens/step] 的饱和，加速比转为负收益。工程上的判据不是\"γ 越大越好\"，而是按专家容量与权重读取带宽上限反解 γ——先测出单专家在目标批下的 token 容量，再取 γ 使验证批次的路由峰值不超过该容量。</p>\n<p>第二类失效来自路由偏好不一致。draft 模型（小稠密模型或 MoE 轻量头）的 token 分布与目标 MoE 逐 token 生成路径的专家命中并不重合，draft 提议的 token 在目标模型中激活的专家往往与自回归路径不同，导致逐位置接受概率 a_i=min(1, p_i/q_i) 系统性偏低，接受率显著低于稠密模型投机的预期。后果是验证算力被大量拒绝位置浪费：γ 个候选里只有最长前缀被接受，其余位置的重采样又引入一次目标分布前向。监控上应把\"每步接受 token 数 / γ\"与\"每步验证触发的专家数\"作为一对联合指标——前者塌陷而后者居高，说明 draft 与目标路由失配，应换 draft 头或缩小 γ，而非继续加大 γ。</p>\n<p>第三类是 KV 一致性缺陷。被拒绝位置用目标分布重采样时，KV 按接受长度批量追加而非逐 token 追加；若截断与 page 归还在批量追加之间交错处理，page table 的长度记录会与实际 KV 内容错位，输出分布出现偏差且难以从 loss 上察觉。诊断手段是对同一 prompt 做\"投机开/关\"的逐 token 概率比对，一旦出现系统性偏移即锁定 KV 追加路径。回滚策略分三级：先把 γ 降到标定值以下并冻结 draft 头；若 OOM 或批抖动仍在，关闭投机、退回纯自回归 decode 以恢复 TPOT SLO；最后回退到上一版 KV 追加实现。批抖动的监控锚点是验证批次的实际路由峰值与排队时长，尾延迟尖刺则对应热点专家溢出后的拆分前向——两者共因，应合并为一个告警而不是分别调参。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>专家容量溢出</td><td>验证批次路由峰值、拆分前向排队时长</td><td>降 γ 至容量标定值</td></tr><tr><td>接受率塌陷</td><td>接受 token/γ、每步专家数</td><td>换 draft 头或缩 γ</td></tr><tr><td>KV 长度错位</td><td>开/关投机的逐 token 概率偏移</td><td>回退 KV 批量追加实现</td></tr></tbody></table>\n<h3 id=\"alg-spec-decode-moe-sec-45\">四十五 · 决策维度：把“同族”拆成可比较的四个轴</h3>\n<p>MoE 投机解码不是孤立算法，它落在一族“用闲置算力换带宽摊薄”的方法中间。要选型，先把族内方法投影到四个可度量的轴上，而不是按名字挑：第一轴是<strong>验证批次是否引入新的专家集合</strong>——普通自回归 decode 每步只读当前 token 命中的专家，投机解码一次验证 γ 个 draft token，路由按 token 独立计算，验证批次命中的专家并集可能远大于单 token 路径；第二轴是<strong>分布是否严格无偏</strong>——拒绝采样保证输出与目标 MoE 一致，而容量因子路由、令牌丢弃这类方法以有偏换吞吐；第三轴是<strong>额外显存与计算归属</strong>——draft 模型或 MoE 轻量头要常驻，与分页 KV、专家权重争同一块 HBM；第四轴是<strong>收益随负载的变化方向</strong>——投机解码的加速比随批大小上升而衰减，因为大 batch 本身已把权重读取摊薄，闲置算力被填满后 γ 的边际收益趋零。</p>\n<p>把这四轴写成可判定的判据，选型就退化成查表。核心不等式是：投机解码只有在“单 token 权重读取时间 ≫ 验证批次新增的路由与排队代价”时才为正收益。用公式表达，设单步 decode 的权重读取时间为 $T_w$、验证 γ 个 token 的专家并集读取时间为 $T_w(\\gamma)$、路由偏斜导致的拆分排队代价为 $T_q(\\gamma)$，则净收益条件为</p>\n<div class=\"formula\">$$\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}&gt;1 \\;\\Longleftrightarrow\\; T_w-T_w(\\gamma) &gt; T_q(\\gamma)+\\gamma\\,c_{\\text{draft}}$$</div>\n<p>其中 $c_{\\text{draft}}$ 是 draft 每 token 的计算代价、$c_{\\text{target}}$ 是目标 MoE 每 token 的验证代价。左端是带宽摊薄收益，右端是路由偏斜与 draft 开销之和。这个不等式直接解释了为什么小 batch、低延迟在线服务是它的主场：$T_w$ 占比高、$T_q$ 尚小；而大 batch 离线吞吐场景左端趋零，右端不降，净收益转负。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-46\">四十六 · 决策表：五种同族方法的适用条件对照</h3>\n<p>下表把 MoE 投机解码与四个最常被拿来比较的同族方法并列。表中“路由扰动”指该方法是否改变验证/执行批次的专家命中分布，“无偏”指输出分布是否与目标模型严格一致。数值只引用材料给定锚点，其余为定性判断。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>方法</th><th>核心换法</th><th>路由扰动</th><th>无偏</th><th>额外显存</th><th>适用条件</th></tr>\n</thead>\n<tbody>\n<tr><td>MoE 投机解码</td><td>γ 个 draft token 并行验证，权重读一次摊到多 token</td><td>高：验证批次专家并集膨胀</td><td>是（拒绝采样）</td><td>draft 模型或轻量头常驻</td><td>在线低延迟 decode、TPOT 主导 SLO、批大小偏小、专家容量有余量</td></tr>\n<tr><td>普通自回归 decode</td><td>逐 token 读权重</td><td>无</td><td>是</td><td>无</td><td>大 batch 吞吐场景、专家已饱和、显存紧张</td></tr>\n<tr><td>容量因子路由与令牌丢弃</td><td>限制每专家容量，溢出 token 丢弃或改道</td><td>中：人为截断改变分布</td><td>否</td><td>无</td><td>专家负载偏斜严重、可接受质量损失换稳定时延</td></tr>\n<tr><td>专家选择路由</td><td>token 选专家改为专家选 token，负载更均衡</td><td>中：路由策略变更</td><td>否（相对原路由）</td><td>无</td><td>训练侧已定型、推理侧需压偏斜，且可接受路由语义变化</td></tr>\n<tr><td>量化 MoE 解码融合大核</td><td>NVFP4/FP8 微缩放 + 融合大核降权重字节数</td><td>无</td><td>近似（量化误差）</td><td>无（反而省）</td><td>权重读取带宽是唯一瓶颈、专家容量充足、可接受量化误差</td></tr>\n</tbody>\n</table>\n<p>读表的关键是两列的互斥关系：<strong>“路由扰动高”与“无偏”在投机解码上同时成立</strong>，这是它区别于容量因子路由与专家选择路由的地方——后两者靠改变路由换稳定，投机解码靠并行验证换带宽摊薄却不改分布。因此当质量不可妥协时，投机解码是族内唯一既提速又不偏的选择；当显存或专家容量已紧，则应退到量化融合大核或普通 decode。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-47\">四十七 · 与量化融合大核的叠加判据</h3>\n<p>量化融合大核与投机解码不在同一维度竞争：前者降 $T_w$ 的分子（权重字节数），后者把 $T_w$ 摊到多个 token 上。二者可叠加，但叠加有次序判据。设量化后单 token 权重读取时间为 $T_w^{q}$，则投机解码的净收益条件变为 $T_w^{q}-T_w^{q}(\\gamma) &gt; T_q(\\gamma)+\\gamma c_{\\text{draft}}$。量化把左端整体缩小，若缩小后左端已小于右端，则投机解码不再划算——这解释了为什么在 NVFP4 权重激活微缩放量化已把带宽压到很低时，γ 的可用窗口会显著收窄，必须重新按专家容量与带宽上限标定，而不是沿用稠密模型的经验 γ。</p>\n<p>工程上的判定顺序应是：先量化把 $T_w$ 压到硬件带宽下限，再测单 token decode 的实际时延构成；若权重读取仍占主导且专家容量有余量，才引入投机解码；若量化后时延已由路由与集合通信主导，则投机解码的 γ 只会放大验证批次的 All-to-All 与专家排队，净收益为负。一个具体例子：在分离式专家并行部署下，验证 γ 个 token 意味着跨节点 All-to-All 的 token 数乘以 γ，通信量随 γ 线性上升，而权重读取只摊薄一次——当互连带宽而非 HBM 带宽成为瓶颈时，投机解码的收益公式左端失效，应优先考虑分离式预填/解码而非加大 γ。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-48\">四十八 · 与容量因子路由、专家选择路由的取舍</h3>\n<p>这三者的共同点是都在处理“专家负载偏斜”，但手段与代价方向相反。容量因子路由用硬容量截断把偏斜压平，代价是丢弃 token、输出有偏；专家选择路由把选择方向反过来，代价是路由语义变更；投机解码不碰路由策略，却因为验证批次按 token 独立路由而<strong>人为制造了一个更大的、分布更偏斜的批次</strong>——γ 个 draft token 的专家并集比单 token 路径更宽，热点专家更容易溢出。因此三者不是替代关系，而是顺序关系：先用容量因子或专家选择把单 token 路径的偏斜压到可接受，再评估投机解码引入的批次膨胀是否仍在专家容量之内。</p>\n<p>判据可写成容量约束：设专家容量为 $C$、单 token 路径热点专家期望负载为 $L_1$、验证批次热点专家期望负载为 $L_\\gamma$，则投机解码可用的条件是 $L_\\gamma \\le C$。若 $L_\\gamma &gt; C$，验证前向被迫拆分或排队，$T_q(\\gamma)$ 迅速吃掉带宽摊薄收益，加速比转负——这正是材料所列的首要失败模式。此时正确动作不是调小 γ 硬撑，而是先改用专家选择路由把 $L_\\gamma$ 压下来，或退回普通 decode。反过来，若单 token 路径本身已因偏斜被迫拆分，投机解码只会加剧问题，容量因子路由才是对症手段。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-49\">四十九 · draft 来源与部署形态的选择</h3>\n<p>draft 模型的选择直接决定 $c_{\\text{draft}}$ 与接受率两个变量。材料给出两条路径：小稠密 draft 模型，或 MoE 自身的轻量头。前者 $c_{\\text{draft}}$ 独立、可离线蒸馏对齐目标分布，但额外显存占用与目标 MoE 争 HBM，在分页 KV 与专家权重共存的显存预算下必须计入；后者不引入外部模型，$c_{\\text{draft}}$ 更低，但轻量头的路由偏好与完整 MoE 的路由偏好不一致，draft token 命中的专家与逐 token 生成路径不同，接受率显著低于稠密模型预期——这是材料明确指出的 MoE 特有问题，也是选型时最容易被低估的一项。</p>\n<p>部署形态上，投机解码与预填解码分离部署存在耦合：验证阶段一次并行处理 γ 个 token，等效于把 decode 批大小乘 γ，若 decode 实例按常规批大小规划容量，γ 膨胀会直接击穿 TPOT SLO。因此 γ 必须与 decode 实例的批大小上限、专家容量、KV page 追加带宽三者联合标定，而不是作为独立超参调。KV 侧还有一个具体机制约束：被接受 token 按接受长度批量追加、被拒绝位置用目标分布重采样，若 page 归还与批量追加交错处理不当，page table 与逻辑长度会不一致，输出分布出现偏差——这条失败模式在分离部署下更易触发，因为预填与解码实例各自持有 page 视图。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-50\">五十 · 选型收口：一张按负载走的判定链</h3>\n<p>把上述判据串成一条可执行的判定链，工程上按顺序问四个问题即可收敛到具体方法。第一问：当前 decode 时延是否由权重读取带宽主导？否，则投机解码不适用，转向通信或调度优化。第二问：专家容量是否有余量容纳 γ 倍膨胀的验证批次？否，则先用专家选择路由或容量因子路由压偏斜，再评估。第三问：量化是否已把带宽压到下限、使左端收益不足？是，则叠加投机解码的窗口已关闭，退回量化融合大核加普通 decode。第四问：质量是否不可妥协？是，则在族内只剩投机解码（拒绝采样无偏），否则可考虑容量因子路由的有偏换稳定。</p>\n<p>这条链的落点是 γ 的标定方式：γ 不是越大越好，而是取满足 $L_\\gamma \\le C$ 且 $\\gamma c_{\\text{draft}} &lt; T_w-T_w(\\gamma)-T_q(\\gamma)$ 的最大整数。材料给出的 2–3 倍加速锚点成立的前提正是这两个约束同时满足；一旦 γ 越过专家容量，验证前向拆分排队使 $T_q$ 非线性上升，加速比转为负收益。因此选型的最终判断不在算法名，而在“专家容量余量 × 带宽占比 × draft 接受率”这三个可测量量的乘积是否为正——这也是把 MoE 投机解码与相邻算法区分开的唯一工程标准。</p>\n\n<h3 id=\"alg-spec-decode-moe-sec-51\">五十一 · 与相邻算法对照：选型边界与失效条件</h3>\n<p>把 MoE 投机解码放回算法族里看，它的直接邻居有三类：普通自回归 decode、稠密模型投机解码、以及增大批量的连续批处理。选型的判据不是“谁更快”，而是“当前瓶颈是否落在权重读取带宽上”。用公式判断：当 <span class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{tokens/step}]}{1+\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}}$$</span> 中的分母项 <span class=\"formula\">$$\\gamma\\,c_{\\text{draft}}/c_{\\text{target}}$$</span> 已经吃掉分子收益时，说明 draft 开销压过了带宽摊薄，此时应退回普通 decode 或改用连续批处理填满算力；反之若 <span class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}]=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha}$$</span> 随 γ 增长仍显著高于 1，且目标 MoE 的专家权重读取次数被摊薄，投机才成立。与稠密投机解码的关键差异在于：MoE 验证阶段的路由按 token 独立计算，draft token 命中的专家与逐 token 生成路径不同，因此稠密模型上标定的 γ 不能直接搬用，必须按专家容量重新标定。</p>\n<table class=\"mini\"><thead><tr><th>对照算法</th><th>适用条件</th><th>不适用/失效信号</th></tr></thead><tbody><tr><td>普通自回归 decode</td><td>批已足够大、算力饱和；或 draft 显存挤占 KV 空间</td><td>TPOT 受带宽限制、算力闲置</td></tr><tr><td>稠密投机解码</td><td>目标模型为稠密、接受率稳定</td><td>直接套用其 γ 到 MoE，接受率骤降</td></tr><tr><td>连续批处理扩容</td><td>请求队列长、吞吐优先于单请求时延</td><td>在线低延迟 SLO 下 TPOT 恶化</td></tr><tr><td>MoE 投机解码</td><td>带宽受限 decode、专家容量有余量</td><td>γ 过大导致验证批次膨胀、热点专家溢出</td></tr></tbody></table>\n<p>失效条件集中在两处。其一是 γ 与专家容量的耦合：γ 过大使验证批次远超 decode 常规批大小，MoE 路由分布偏斜，热点专家容量溢出，验证前向被迫拆分或排队，加速比转为负收益——这正是“2–3 倍”加速只在标定区间内成立的边界。其二是路由偏好不一致：draft 模型（小稠密模型或 MoE 自身轻量头）的专家选择与目标 MoE 逐 token 路径不同，被拒绝位置白耗验证算力，接受率低于稠密预期。工程上应把 γ 按专家容量与带宽上限联合标定，并以接受长度分布而非平均接受率作为调参信号。</p>\n<p>还有一处系统代价容易被忽略：被拒绝位置用目标分布重采样时，若 KV 追加与截断处理不当，page 归还与批量追加交错会造成 KV cache 长度与 page table 不一致，输出分布出现偏差。因此选型时要把“按接受长度批量追加 KV”视为方案的一部分而非优化项——它既是减少碎片的手段，也是正确性前提。当 draft 模型的显存开销挤压 KV 块预算、或专家容量无法容纳膨胀后的验证批次时，该方案的收益边界即被触及，应转向连续批处理或分离式预填/解码来消化算力闲置。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · 分离式预填/解码与批调度</td></tr><tr><td>解决什么</td><td>MoE decode 阶段每 token 只激活少量专家，GPU 算力大量闲置而时延受权重读取带宽限制；自回归逐 to…</td></tr><tr><td>一句话机制</td><td>用一个小稠密 draft 模型或 MoE 自身的轻量头一次提议 γ 个 token，目标 MoE 模型并行验证这 γ …</td></tr><tr><td>代价与失效</td><td>draft 模型本身有显存与计算开销，γ 过大时验证批次膨胀导致 MoE 路由负载不均、专家溢出；MoE 路由对 draft token …</td></tr><tr><td>后继</td><td>专家并行 All-to-All 调度</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-spec-decode-moe · 共 8 个片段</p>\n";break;}}})();
